INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола ҳамаи маълумот дар бораи фосилаи оптималии шитори нӯри тип барои қаришкунӣи наҳӯрӣ оварда шудааст. Истифодаи ин маълумот ба зиёд кардани ҳосилнокӣ ва сифати ғалла кӯмак мекунад.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
