INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддимаи парвариши сорго ва зарурати обёрории муосир</h2><p>Сорго яке аз муҳимтарин навъҳои донӣ ва чарогоҳӣ дар минатоқи нимухшуру хушк буда, ба сабаби тобоварии баландаш ба стресси гармӣ ва камобӣ, ҷойгоҳи махсусро дар кишоварзии устувор ёфтааст. Аммо барои расидан ба самаранокии баланд, танҳо парварии он кофӣ нест; идоракунии дақиқи манбаъҳои об аҳамияти ҳаётӣ дорад. Истифодаи системаҳои обёрории қатра-қатра, усули самаранок барои таъмини оби решаҳост, ки боиси кам шудани бухоршавӣ ва хароҷоти об мегардад. Дар ин дастур мо раванди парвариши сорғо аз ибто то устувориро бо диққати хос ба асосҳои обёрории қатра-қатравӣ ва чизии (нирӣ) баррасӣ мекунем. Ин раста ба сабаби геноми тобовараш қобилияти баланди фурӯ бардории оби қитъаҳои чуқури хокро дорад, ки дар сурати танзими дурусти системаи обёрорӣ самаранокии фавқулоддароро ба вуҷуд меорад. Парвариши сорго бо афтаи нав на танҳо истеъмоли обро то 40% кам мекунад, балки бо тақсимоти якхелаи намӣ, пеш аз рух додани мушкилоти муҳит, асоси мустаҳкамро барои афзоиши тезтари раста месозад. Бинобар ин, фahmeи амиқ динамикаи обёрории қатра-қатра барои ҳар деҳқони фаъол дар ин соҳа ҷойнаест.</p>\n\n<h2>Усулҳои парвариши сорго мувофиқ бо обёрории қатра-қатравӣ</h2><h3>Тасвиркунӣ ниҳоӣ ва тайёр кардани асос (бистар)</h3><p>Муҳимтарин марҳилаи пеш аз нобуд кардани бӯри хок аст. Дар системаҳои қатрагири, сатҳи замин бояд ҳамвор бошад, то ки фишори собит дар тамоми дарозии хатҳо таъмин гардад. Соргоҳ одатан бо фосилаи сатҳӣ 60 то 75 сантиметр ғундохта мешавад. Ин фосилагӣ имкон медиҳад, ки нӯри тиббӣ ё ӯзан асосӣ ба осонӣ дар мобошӣ ё канори сатҳҳо ҷойгир шавад. Агар аз ӯзанҳои шаффоф хурдтар истифода мекунед, ҳатман аз ӯзани ғилдидаи 2 дюйм ҳамчун хати асосии интиқолдор дар оғози блок истифода баред, то камшавии муҳими фишор дар тӯли роҳ вуҷуд надорад. Инчунин, ҷамокии чуқур ва нест кардани санглохҳо пеш аз насби ӯзанҳо монеаи зарари физикӣ ба нӯри тиббӣ ҳангоми ғундотан мешавад. Бӯри бояд чунин бошад, ки решаҳо тавонанд озодона дар қабатҳои гуногуни хок паҳн шаванд.</p><h3>Роҳи ғундотан ва танзими фосилаҳо</h3><p>Бадони соргоҳро ғундагирӣ мекунед, беҳтар аст, ки дақиқан дар ҷойи дӯст хатти ҳаракати нӯри тиббӣ ҷойгир шаванд, то ки об ва моддаҳои ғизоӣ мустақиман ба минтақаи решаҳо расанд. Ғундотан бо мошинҳои ним-механизатсияшуда бо нӯри тиббӣпун дақиқии баланд дорад. Дар ҳолати ғундотани дастӣ, диққат диҳед, ки бадонҳо бо қатрагирандаҳои рӯи нӯр тамос нагиранд ва осеб нарасонанд. Фосилаи мувофиқ байни бадонҳо дар сатҳ ҳам бояд байни 10 то 15 сантиметр бошад, то аз рақобати сахти ноҷавонон барои рӯшноӣ ва об пешгирӣ шавад. Ин ҷойгиркунии мунтазам имкони назорати беҳтари рӯйшӣ ва кам кардани зарари бемориҳоро низ фароҳам меояд.</p>\n\n\n<h2>Ҷадвали тақвири қатрагирии соргоҳ</h2><p>Идоракунии об дар марҳилаҳои гуногуни афзоиши сургум хеле ҳассос аст. Барномаи мунтазам барои оборӣ вуҷуд надорад, балки бояд вобаста ба ҳарорати ҳаво, намии хок ва марҳилаи афзоиши растани танзим карда шавад. Дар ҳамагӣ, сургум дар мавсум ба тақрибан 400 то 600 миллиметр об ниёз дорад. Дар системаи қатрагӣ, шумо ин миқдорро ба қисмҳои хурдтар (ҳарфҳои оборӣ) тақсим мекунед. Танзими дурусти вақт калиди муваффақӣ дар ин марҳила аст; зеро оборӣ бо эрта навириш метавонад решаҳоро ханоб карда, ва оборӣ дершавошӣ метавонад боиси парешони донаҳо ё гулҳо гардад. Бинобар ин, назорати мунтазами намии хок бо намиеъёбкунандаҳои рақамӣ маъруфатҳои қатъии мо ба деҳқоони арҷманд аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-سورگوم-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="راهنمای جامع کاشت سورگوم با آبیاری قطره‌ای - تصویر 1"/><figcaption>усулҳои кӯркортанӣ, оборӣ бо қатра, барномаи оборӣ, сургум</figcaption></figure><table><thead><tr><th>Марҳилаи афзоиши сургум</th><th>Мӯҳлати вақт</th><th>Тавсияҳои оборӣ бо қатра</th></tr></thead><tbody><tr><td>Аз наввиш то 4 барг</td><td>Ҳафтаи 1 то 3</td><td>Обориҳои боз ва рат (ҳар 2-3 рӯз) барои нигоҳ доштани намии дунбур ва навбур</td></tr><tr><td>Рушди фаъол вегетативӣ</td><td>Ҳафтаҳои 4 то 8</td><td>Комаи камтар (ҳар 4-5 рӯз) бо зиёд кардани ҳаҷми об; мустаҳкам кардани решаҳо</td></tr><tr><td>Ғӯлашонӣ ва сабукидӣ</td><td>Ҳафтаҳои 9 то 12</td><td>Ҳассосияти ҳадди аксар ба норасоии об; комаи мунтазам ҳар 3 рӯз, пешгирии хушк шудани полоса</td></tr><tr><td>Гиря ва пухтани дон</td><td>Ҳафтаҳои 13 то 16</td><td>Кам кардан тадриҷии обёрӣ барои омодагӣ ба ҷамъоварӣ</td></tr></tbody></table><p>Диққат диҳед, ки ин рақамҳо тақрибан ҳастанд ва бояд бо палмасенсҳои хокӣ ё таҳлилҳои хокии маҳаллӣ тасдиқ шаванд. Мақсади асосӣ дар он аст, ки фишори обӣ ба аълои расад, ба истиснои марҳалаи ҳассоси гулдорӣ. Дар ин марҳилаҳо, камтарин сатҳи намии хок метавонад боиси камшавии назаррас дар вазни дона ва сифати ниҳоии mahsulот шавад.</p>\n\n\n<h2>Нуктаҳои амалӣ барои идоракунии навири ғарди дар боғзорҳои сургу</h2><ul><li><strong>Санҷиши фишор:</strong> Пеш аз оғоzi овардани об, фишори система-ро санҷед. Фишори радиаллии навири ғардӣ одатан байни 1 то 2 бар бояд бошад. Фишори баланд боиси кордузӣи зуд-зудшавии навир мебошад ва умри кории онро кам мекунад. Истифодаи регулятори фишор ҳалли мувофиқ барои нигоҳ доштани мувозинат аст.</li><li><strong>Тоza кардани филтрҳо:</strong> Сургу решаҳои нисбатан вазнин дорад ва метавонад зарраҳои хурди хок ба навири ғардӣ ворид нашаванд, аммо агар филтрҳо пур шуда бошанд, навир метавонад махлӯл шавад. Мутақан аз филтрҳои рехӣ ё шабакавии сифатнок истифода баред ва ҳар ҳафта онҳоро санҷед.</li><li><strong>Нигоҳ доштани солимӣи навир:</strong> Аз ҳаракат кардан ё кашидан нӯрҳои дақиликӣ бо асбоби калон ё ҳайвонот пешгирӣ кунед. Нӯрҳои дақиликӣ ба UV ҳассосанд; агар нӯр дар сатҳи замин бошад, кӯшиш кунед, ки онро дар тӯли рӯз бо баргҳои растаниҳо ё хок пӯшонед, то аз вайроншавии он пешгирӣ шавад.</li><li><strong>Пайвастшавии дуруст:</strong> Ҳангоми пайваст кардани нӯр ба лӯлаи асосӣ, аз пайвандҳои лӯлоӣ ё пластикӣ бо сифати баланд истифода баред. Нӯраҳои хурд дар тӯли фасл метавонанд боиси кам шудани номаёни фишор дар охирони нӯр гарданд. Пайвандҳоро бо часпӯдҳои махсус хатм кунед.</li></ul><p>Илова бар сургоҳ, принсипҳои монандро барои дигар растаниҳо бо решаи чуқур риоя кардан лозим аст. Масалан, агар дар заминии худ растаниҳои дигареро монанди <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D9%85%D8%A7%D8%B4-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Миёни ҳосилнокии шафтобӯр дар гектар</a> дар назар гирифта бошед, талаботи обии гуногун аст. Аммо технологияи нӯрҳои дақиликӣ васеъшаванда аст. идоракунии якҷояи обёрӣ барои ҳамаи кӯдакҳои занҷирӣ, боҳири нашрҳоро дар пай овард.</p>\n\n\n<h2>Саволҳои мавруди (FAQ)</h2><h3>Оё нӯри дақиликиро барои чанд фасл истифода бардан мумкин аст?</h3><p>Бале, набулҳои босирип баланд одо ду то се мавсим истифода шуда метавонанд. Агар паррасии мувофiq дошта шавад, умри онҳо зиёдтар мешавад. Пас аз анҷоми мавсим, набулҳоро тоза кунед ва пайчонида дар ҷои хунук ва дур аз нури мустақим ҷойгир кунед. Шустани ниҳоӣ бо оби тоза аз пайдоиши калҳо дар дохили набул пешгирӣ мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-سورگوم-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="راهنمای جامع کاشت سورگوم با آبیاری قطره‌ای - تصویر 2"/><figcaption>усулҳои тармоҳӣ, обёрӣ, ҷадвали обёрӣ, сугоро</figcaption></figure><h3>Чӣ тавр аз ғилломиши набулҳо пешгирӣ кунам?</h3><p>Истифодаи филтри мувофиқ, шустани мунтазами система дар афсари рӯз ва нагузоридани истифодаи абзори кӯҳкор ё маҳлулҳои ғализ бе қадим аз роҳи набул аз муҳимтарин омилҳои пешгирӣ аз ғилломиш мебошад. ҳамеша обшӯӣ-ро дар оғози система иҷро кунед ва аз танкҳои захираи оби тоза истифода баред.</p><h3>Оё обёрӣ барои сугорои дарам мувофиқ аст?</h3><p>Гарчанде сугоро наботати тобовар аст, вале обёрӣ ҳатто дар шартҳои ним-дарам самараро ба таври назаррас зиёд мекунад. Ин усул ба шумо имкон медиҳад манбаъҳои маҳдуди обро бо дақиқии баланд ба решаҳо расонед. Камои стресси обӣ бевосита ба зиёдшавии ҳосили дона мусоидат мекунад.</p>\n\n\n<h2>Хулоса ва пайдарпаӣ</h2><p>Тармоҳии сугоро бо обёрӣ ва набул босирип, омезиша аст, ки чархи кишоварзии шуморо аз ҷиҳати иқтисодӣ ва муҳити зист вайрон карда метавонад. Бо риояи асосҳои тайёркардани таъбир, интихоби масофаи мувофиқ ва назорати доимии системаи обёрӣ, шумо на танҳо хароҷотҳои обро кам мекунед, балки сифат ва миқдори донаҳои дугараро низ беҳтар мекунед. Барои маълумоти бештар дар бораи идоракунии кишоварзии дигар, метавонед миқдори бодаи аспинаж дар гектар + омилҳои таъсиррасон ва усулҳои зиёдкарданро низ омӯзед. Мувосса дар обёрӣ босирип дар ҷузъиёти ҳидда аст; пас намоиш ҳазир кунед ва аз нозуктарин нӯшероҳо бехабар нашавед. Инчунин, ошноӣ бо миқдори бодаи гунараи дарам дар гектар: раҳнамои комил дар кишоварзӣ метавонад ба шумо диди беҳтар диҳад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/راهنمای-جامع-کاشت-سورگوم-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="راهنمای جامع کاشت سورگوم با آبیاری قطره‌ای - تصویر 3"/><figcaption>усулҳои парҳез, ороиши қатқа, нақшаи обӣ барои зирагӣ, сорго</figcaption></figure>\n<p><strong>Маводи алоқаманд:</strong> <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%db%8c%d9%88%d9%86%d8%ac%d9%87-%d9%87%d9%85%d8%af%d8%a7%d9%86%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори борони ороишӣ дар як ҳектар + омили таъсиррасонанда</a>, <a href="https://navar-abyari.ir/barley-seed-rate-per-hectare-iraq/">barley seed rate per hectare iraq</a></p>\n<p><strong>Маводи алоқаманд:</strong> <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%da%af%d9%86%d8%af%d9%85-%d8%af%db%8c%d9%85-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори борони ҷавдорӣ дар як ҳектар: роҳнамои умумӣ</a></p>','Комил раҳнамои ғироҳи ғуруҳ тавассути пестонии тамдид','Сорго — рахшакест, ки дар ситои дурусти ободории тамғагӣ ва бастабарӣ метавонад самаранокии баланд дошта бошад. Ин мақола тафсилиҳои техникӣ бар партофт ва ободориро баррасӣ мекунад.','publish','closed','closed','comil-rahnamoyi-ghuqur-gharoh',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
