INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على الطرق الفعالة لمكافحة الآفات والأمراض في محصول الذرة عبر نظام الري بالتنقيط، مع إرشادات عملية شاملة للمزارعين لتحسين الإنتاجية وحماية المحصول.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
