INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола дар бораи модирияти зарароварҳо ва бемориҳои буғдом тавассути истифодаи системаи суғории томчавӣ ва роҳҳои беҳтарини пешгириӣ барои деҳқонон муҳокӣ мешаванд. Барои давидан ба фармоиш доиши давидон, то 15% дар хамон сарборон. Дар ҳолати саволҳо ва ҷавобҳои фарзӣ, бо роҳи бевосита бо AFP, тавсеяи муҳандисии ҷаҳонӣ. Барои таҳсилоти ҷойбӯр, ҳолатҳои фарҳангӣ ва соҳибкорона, дар маҷаллаи AFP, то 10% дар хамон сарборон. Ҷавобҳои саволҳо барои ҳоло аз пайи дахшӣ ва илми муҳим.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'rank_math_focus_keyword','Модирияти зарароварҳо ва бемориҳои буғдом бо системаи суғории томчавӣ: Раҳбарии пурра барои деҳқонҳо' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='rank_math_focus_keyword');
INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='tj' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>المقدمة: العلاقة بين الري بالتنقيط وصحة نبات الخيار</h2><p>أصبح زرع الخيار، نظراً لسرعته في النمو وحساسيته العالية للإجهاد المائي واستهلاكه النسبي المرتفع للماء، من أكثر المحاصيل البستانية رواجاً واهتماماً في العراق. ومن جهة أخرى، فإن الخيار شديد الحساسية للبيئات الرطبة وتقلبات الرطوبة، مما يؤدي إلى الإصابة بالأمراض الفطرية والبكتيرية، وهي من أكبر التحديات التي يواجهها المنتجون. كثير من المزارعين يظنون أن الري بالتنقيط يقتصر على توفير الماء، لكن الحقيقة أن هذه التقنية المتقدمة هي من أقوى أدوات الإدارة لـ <strong>الآفات والأمراض المرتبطة بالخيار</strong> وتحقيق ذلك من خلال التحكم الدقيق في رطوبة الأوراق والتربة، مما يكسر دورة حياة العديد من الدوديّات والديدان القشرية والآفات الحياضية، ويبني الأساس لنمو موحّد وصحي للنبات. هذا النهج المتكامل لا يقلل تكاليف المكافحة بالمبيدات فقط، بل يحسّن أيضاً الجودة النهائية للمحصول.</p><p>فيما يلي، سنقيّم التفاعل التقني والتطبيقي بين أنظمة الري بالتنقيط وأحزمة الري والصحة النباتية للخيار، بهدف صياغة استراتيجية أفضل لتقليل الأضرار الناتجة عن الماء والبيولوجيا. كما سنتناول الدور الحيوي في التغذية المحلولة ومراقبة المعاملات الفيزيائية للماء في الوقاية من العدوى الثانوية.</p>\n\n\n\n<h2>التأثير الفسيولوجي للري بالتنقيط على إدارة الآفات</h2><h3>خفض الرطوبة النسبية على سطح الأوراق</h3><p>تفضل العديد من آفات الخيار، وعلى رأسها المن الأبيض والذبابة البيضاء واللطاخة، البيئات الرطبة لتضع بيضها وتزداد وتتكاثر. في أنظمة الري الخاطئة (الري بالرش أو الغسيل السطحي)، تتصرف قطرات الماء كجسيمات غلسرين مجهرية وتولّد قوى سطحية تيسّر طرد الأبواغ الفطرية والبكتيرية من التربة نحو الأوراق. لكن في <strong>الري بالتنقيط</strong> و الري النطفي، حيث يتم وضع الماء فقط في منطقة الجذور (Root Zone) وسطح التربة. هذا يؤدي إلى بقاء سطح القمع والأوراق جافة دائمًا، وبذلك تزداد مقاومة النبات ضد الأمراض الفطرية، بما في ذلك العفن الأبيض والفساد الأسود والبوترتس. الحفاظ على الجفاف النسبي للأوراق يعزز أول خط دفاعي للنبات ضد العدوى التي ينقلها الهواء، ويقلل بشكل كبير من الحاجة إلى استخدام مبيدات الفطريات واسعة الطيف.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-خیار-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های خیار با آبیاری قطره‌ای - تصویر 1"/><figcaption>أضرار المحاصيل وأمراضها، الري بالتنقيط، الخيار</figcaption></figure>\n<h3>مكافحة الآفات الحية في التربة من خلال التغذية السائلة</h3><p>من بين المزايا الخفية والقياسية لنظم الري بالتنقيط هي القدرة <em>التغذية السائلة</em> أو التغذية السائلة من خلال الجذور. من خلال إضافة المعادلات (البكتيريا المفيدة مثل <em>Bacillus subtilis</em> و <em>Pseudomonas fluorescens</em>أو من خلال المبيدات الحيوية ومبيدات الأعشاب الانتقائية في نظام الري، يمكن حماية جذور الخيار مباشرةً من عدوى جُذور الكُرنَة (الديدان الخيطية) والتعفنات التربة. هذا النهج يوفر فعالية أعلى في مكافحة الآفات تحت السطحية مقارنةً بالرش السطحي أو التناثر، لأن المواد المستهلكة تُحقن مباشرةً في منطقة الجذور وتضمن امتصاصًا مثاليًا.</p>\n<h2>الأمراض الفطرية والبكتيرية في الخيار ودور الري بالتنقيط.</h2><h3>تعفن الجذور (Meloidogyne spp.)</h3><p>تُعد الدودة الخيطية من أهم الآفات التربة في الخيار، حيث تسبب تكوين عقد على الجذور، وضعف النبات، ووفاته في النهاية. يوفر الري بالتنقيط، بفضل تركيزه على منطقة الجذور وإمكانية التحكم الدقيق في عمق الرطوبة، إدارة تدريجية لمجموعة الدودة الخيطية. من خلال تقليل تركيز الأسمدة الآزوتية في المراحل الحساسة والتحكم الدقيق في الموصلية الكهربية (EC) للمحلول، يمكن منع النمو المفرط للجذور الجانبية، وهي الهدف الأساسي للديدان الخيطية. كما أن استخدام مخلفات الطماطم في برنامج الري يمكن أن يعمل كطريقة مساعدة وعضوية لتقليل مجموعة الدودة الخيطية وتغيير تكوين الميكروبات في التربة. تخلق هذه الاستراتيجيات المركبة خط دفاع قوي ضد هذه الآفة المدمرة.</p>\n<h3>الطسوة (Downy Mildew)</h3><p>تتكاثر الطسوة (العفن الدقيقي) بقوة في ظروف رطوبة عالية للأوراق ودرجة حرارة معتدلة، وتلوث الحقل بالكامل بسرعة. في البيوت المحمية، يؤدي ضعف التهوية المناسب مع الري الخاطئ إلى كارثة على الخيار. من خلال استخدام الري بالتنقيط، تظل رطوبة التربة مستقرة وقابلة للتنبؤ، بينما يتم التحكم في رطوبة هواء الدفيئة من خلال تنظيم الغسيل، والتهوية، ودرجة الحرارة المحيطة. هذا التوازن الدقيق يغلق النافذة الزمنية الملائمة لنشاط وقمع العفن، مما يتيح للمزارع التحكم في الرطوبة الضارة مع تقليل استهلاك المبيدات الفطرية.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-خیار-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های خیار با آبیاری قطره‌ای - تصویر 2"/><figcaption>أفات ومراض المحاصيل الري بالتنقيع خيار</figcaption></figure>\n\n\n\n\n<h3>طكسسبوروس وفاشاريوم (فطر فوساريوم)</h3><p>التمنن البني للجذور (فوساريوم) واحد من امراض الخيار القاتلة اللي تدخل للجذور عن طريق التربة. ري بالتنقيع اللي يبلل جزء من التربة ويخلي الباقي جاف يقلل من انتشار الفطر على سطح التربة. وإنو ما هي تحكم مطلق، لكنها تبطيء انتشاره الأفقي. ننصح في الزراعات الجديدة تستخدمون بذور مقاومة للتمنن البني، و تسوون إعداد عميق لنظام الري لتاخذ الجذور الرئيسية رطوبة كافية بالعمق المناسب. هالعمق يقلل ان الجذور تتعرض للمناطق الملوثة بالفطريات السطحية.</p>\n<h2>نقاط عملية لتكامل الري وإدارة الأفات</h2><ul><li><strong>تقسيم خطوط الري:</strong> في المزارع الكبيرة، قسموا النظام لأقسام مستقلة. إذا شوفوا تلوث سريري في وحدة، ممكن تنقصوها من الخط الرئيسي وتنفذوا لها برنامج رش أو تغذية مضادة للفطريات (ديتارو) خاص بدون ما تؤثر على باقي المزرعة. هالأسلوب اللي اسمه الإدارة الدقيقة يساعدكم تتجنبوا رش المبيدات على المزارع السليمة.</li><li><strong>تنقية الماء:</strong> ري الخيار بماء الصرف أو بئر، يحتاج فلترة دقيقة (شبك 120 و150). انسداد القطارات يسبب هبوط الضغط وتغير نمط الري، وهذا ممكن يسوي اجهاد التربة ويقلل قوة النبات ضد الأفات. متابعة الفلاتر بانتظام ضرورية.</li><li><strong>إدارة EC وpH للمحلول:</strong> البطاطا حساسة لدرجة الحموضة pH بين 5.5 و6.2. إذا ارتفع pH المحلول، ينخفض امتصاص الحديد والزنك ويضعف النبات؛ والنبات الضعيف يصبح الهدف الرئيسي لحشرات الجراد والذبابة البيضاء. مراقبة pH ماء الري أسبوعياً ضرورية. ضبط جودة الماء يعني امتلاك نبات أقوى ضد الأمراض.</li></ul>\n<h2>الأسئلة الشائعة (FAQ)</h2><ol><li><strong>هل يمكن للري بالتنقيط أن يقلل حشرات الجراد؟</strong><br>نعم، بشكل غير مباشر. من خلال الحفاظ على جفاف الأوراق وزيادة مقاومة النبات عن طريق التغذية المتوازنة، تصبح حشرات الجراد أقل في الإصابة. كما يمكنك حقن المبيدات الدافينغر عبر نظام التنقيط لتسهيل امتصاص السم في الأوراق.</li><li><strong>ما هو أفضل وقت للرذاذ عبر التنقيط (Dytario)؟</strong><br>أفضل وقت هو عندما تكون متأكداً من وجود آفات جذرية أو آفات العقد الجذرية. عادةً في منتصف موسم الإثمار وقبل ذروة الحصاد، للتحكم في التفسخ. بالنسبة لآفات الأوراق، يظل الرش العادي أكثر فعالية، ولكن Dyntario يفضل للتحكم في الآفات الحية في التربة.</li><li><strong>هل الصمغة الشريطية مناسبة أكثر للبذرة أم التنقيط؟</strong><br>نوار قلاب (میکرو تیوب) بسیار محبوب برای خیار گلخانه‌ای است زیرا پوشش یکدست‌تری ایجاد می‌کند و در برابر گرفتگی مقاوم‌تر است. اما برای خیار باغی و فضای باز، قطره‌چکان‌های ۱.۶ میلی‌متر یا بالاتر به دلیل نیاز بیشتر خیار به آب، گزینه بهتری است. انتخاب بین این دو به <a href="https://navar-abyari.ir/tarzi-intihobi-tasmai-obyari-nuqtagiri-muvofiq/">روش انتخاب صحیح تجهیزات آبیاری</a> بستگی دارد.</li></ol>\n<h2>جمع‌بندی</h2><p>مدیریت آفات و بیماری‌های خیار، فراتر از مبارزه با حشرات است؛ این یک بازی شیمیایی و فیزیکی است. استفاده از <strong>آبیاری قطره‌ای</strong> و نوار قلاب، به شما امکان مدیریت بهتری می‌دهد تا رطوبت ریشه‌ای را بهینه کنید و از پراکندگی اسپور قارچ جلوگیری کنید. با داده‌های دقیق می‌توانید آنتاگونیست‌ها را مستقیماً به ریشه برسانید و با پایش pH و EC، ایمنی گیاه را در برابر لکه‌های برگ حفظ کنید.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-خیار-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های خیار با آبیاری قطره‌ای - تصویر 3"/><figcaption>آفات و بیماری‌های محصول، آبیاری قطره‌ای، خیار</figcaption></figure>\n<p>تذكر أن نظام الري عندك ما هو مجرد أداة لنقل الماء، بل هو نظام لإدارة صحة المزرعة. مع الأخذ بعين الاعتبار الفروقات المناطقية، مراجعة مصادر متخصصة أخرى مثل <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%aa%d9%88%d8%aa-%d9%81%d8%b1%d9%86%da%af%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">معدلات إنتاج الفراولة للهكتار: العوامل وطرق زيادتها</a> أو المحاصيل الجانبية الأخرى يمكن أن تساعدك في دورة المحاصيل وإدارة المزرعة ككل. كما أن فحص <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%ac%d9%88-%d8%a8%d9%87%d8%a7%d8%b1%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">معدلات إنتاج الشعير الربيعي للهكتار</a> مفيد للتخطيط للمحاصيل المتسلسلة. للحصول على المزيد من المعلومات حول <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d9%be%db%8c%d8%a7%d8%b2%da%86%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">معدلات إنتاج البصل (الزحف) للهكتار</a> يمكنك أيضاً قراءة أدلة إرشادية لنا. في النهاية، نظام ري سليم هو نصف الطريق نحو محصول خیار خالٍ من العيوب.</p>\n<p><strong>مقالات ذات صلة:</strong> مقدار محصول الفراولة في الهكتار: العوامل وطرق زيادة الإنتاج، <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d9%be%db%8c%d8%a7%d8%b2%da%86%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">مقدار محصول البصل الصغير في الهكتار: دليل شامل + نصائح للزيادة</a>، <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%ac%d9%88-%d8%a8%d9%87%d8%a7%d8%b1%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">مقدار محصول الشعير الربيعي في الهكتار: حلول عملية وحديثة</a>، <a href="https://navar-abyari.ir/tarzi-intihobi-tasmai-obyari-nuqtagiri-muvofiq/">ترتيب اختيار أنظمة الري بالتنقيط الناجحة</a></p>','أضرار وأمراض خيار الري بالتنقيط: استراتيجيات الوقاية والسيطرة','الري بالتنقيط ليس مجرد مصدر للرطوبة فحسب، بل يلعب دوراً أساسياً في الوقاية من انتشار الأمراض التربة، وتقليل الحاجة إلى المبيدات. في هذا المقال، سنناقش بعمق الآفات والأمراض الشائعة في الخيار تحت تأثير الري بالتنقيط والتعبئة.','publish','closed','closed','diseases-pests-drip-irrigation-cucumbers-iraq',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
