INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Алоқаи ирригатсияи буррокунак бо саломатии барги кия</h2><p>Кабоди кия ба сабаби рӯйшди тез, ҳассосияти баланд ба шиддати об ва истеъмоли нисбатан зиёди об яке аз маҳсулоти боғдории мураттабтар ва муҳимтарин дар Ирон гардидааст. Аз ҷониби дигар, кия ба муҳитҳои номоғз ва тағйироти босирати босират ҳассос аст ва бо бемориҳои қорӣ ва бактериявӣ оلودа шудан яке аз бузургтарин мушкилоти истеъмолиёнро ба вуҷуд меорад. Бисёре аз деҳқонҳо фикр мекунанд, ки ирригатсияи буррокунак танҳо дар истифодаи об сарфа кардан аст, аммо ҳақиқат ин аст, ки ин технологияи пешрафта яке аз қавитарин воситаҳои идоракунӣ барои назорати <strong>зарароварҳо ва бемориҳои кия</strong> ҳисоб мешавад. Бо назорати дақиқи босирати баргу замин, имкон дорад, ки давраи ҳаёти бисёр зарароварони хушишакл, нармоён ва зарароварони заминӣро вайрон карда, заминаи рушди якхела ва саломати барги кияро фароҳам овардан. Ин равиши ҷамъбастӣ на танҳо хараҷҳои заҳропашӣ-ро кам мекунад, балки сифати ниҳоии маҳсулотро низ беҳтар менамояд.</p><p>Дар идома, мо муносибатҳои техникӣ ва амалӣ байни системҳои ирригатсияи буррокунак ва шӯни хаттӣ бо саломатии барги кияро омехта мекунем, то стратегияи беҳтар барои кам кардани зиёни обӣ ва биологӣ дошта бошем. Инчунин дар бораи нақши ҳаётии гузаштани маҳлул ва назорати параметрҳои физикии об дар пешгирии ғамусҳои иддакӣ сӯҳбат мекунем.</p>\n\n\n\n<h2>Таъсири физиологии ирригатсияи буррокунак ба идоракунии зарароварон</h2><h3>Кам кардани босирати нисбии сатҳи барг</h3><p>Бисёре аз зарароварони кия, ба таври асосӣ зарароварони барг, мурғачаҳои сафед ва ҳарилҳои заминӣ, муҳитҳои номоғзро барои тулдухур, пӯшида шудан ва зиёд кардан интихоб мекунанд. Дар системҳои ирригатсияи нодуруст (ирригатсияи боронӣ ё шустанушуи сатҳӣ), чуқораки об чун глизеринҳои микро скопии амал мекунанд ва плизодогомияро ба вуҷуд меоранд, ки боиси партофтани спорҳои қорӣ ва бактерияҳо аз замин ба барг мегардад. Аммо дар <strong>оқовиш қатра-қатра</strong> ва нӯҳаи тап, об танҳо дар минтакаи реша (Root Zone) ва сатҳи хок ҷой мегирад. Ин боиси он мешияд, ки сатҳи обшӯр ва барг ҳамеша хушк боқӣ мемонад ва ин тавр, муқовимати бутаборо ба бемориҳои моғол, пӯзиҳои сиёҳ ва ботритис зиёд мешавад. Захири хушкӣ нисбии барг, қирриҳи муқовимати аввалинаро дар баробари сироятҳои парваришкунанда тақвият мебахшад ва ниёз ба истифодаи қоричкунаки васеҳ-алкосидиро ба таври назаррас кам мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-خیار-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های خیار با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation хӯш</figcaption></figure>\n<h3>идоракунии зараррасониҳои хокзамин тавассути ғизои майи</h3><p> яке аз арзишҳои дафншуда ва хеле муҳими системаҳои қатра-қатра, имконият <em>дидатсӣ</em> ё ғизои майи тавассути реша аст. Бо илова кардани антагонистҳо (бактерияҳои фоидаоваранде <em>Bacillus subtilis</em> ва <em>Pseudomonas fluorescens</em>) ё ё ё биологӣ ва ҳашаркушҳои тавҷҷиҳшуда ба системаи обёрӣ, метавон бевосита ба решаҳои хияр кӯмак кард, то аз хушунҳои реша (решаҳашарҳо) ва пӯшидани хокӣ ҳимоя шавад. Ин усул нисбат ба пҳови сатҳӣ ё арафшавӣ, самаранокии баландтарро дар назорати ҳашарҳои зери хок дорад, зеро моддаҳои сарфшуда бевосита ба минтақаи решаҳо инъикор мешаванд ва ҷабби беҳтаринро таъмин мекунанд.</p>\n<h2>Бемориҳои қамарӣ ва бактериявӣ дар хияр ва нақши обёрии навъи ғаллоки</h2><h3>Пӯшидани реша (Meloidogyne spp.)</h3><p>Решаҳашар яке аз муҳимтарин ҳашарҳои зери хок барои хияр аст, ки боиси пайдоиши гӯбаҳо дар решаҳо, заифии растани ва дар натиҷа марги ниҳоии буттаҳо мегардад. Обёрии навъи ғаллоки, ба сабаби ғам бар додани минтақаи реша ва имконияти назорати дақиқи чуқурии намнокӣ, имконияти идоракунии тадриҷии популятсияи решаҳашарҳоро фароҳам меорад. Бо кам кардани консентратсияи навиқ аз нитроген дар давраҳои ҳассос ва назорати дақиқи EC-и маҳлул, метавон аз афзоеши зиёди решаҳои паҳлӯвӣ, ки ҳадафи асосии решаҳашарҳо мебошанд, пешгирӣ кард. Инчунин, истифодаи шараби гӯбӣ ё гӯбгӯш дар барномаи обёрӣ метавонад ҳамчун усули кӯмакӣ ва органикӣ барои кам кардани популятсияи решаҳашарҳо ва иваз кардани микробсозии хок амал кунанд. Ин стратегияҳои муттаҳид, сатҳи муҳофизати қавватӣро дар муқобили ин зараррасандаи вайронкунанда пайдо мекунанд.</p>\n<h3>Давонам (Downy Mildew)</h3><p>Давонам (қамари пӯшидан) дар шароити баландии намнокии баргҳо ва ҳарорати мукаффи ба таври интенсивӣ таъмир мекунад ва ба таври тезу тиз тамоми ҳашамро хушун мекунед. Дар хонаҳои шисҳидашуда, набудани ҳавои дуруст бо обёрии нодуруст, фанос барои хияр аст. Бо истифода аз ғаллоки, намноки хок собит ва пешбиникор боқӣ мемонад, аммо намноки ҳавои хонаи шисҳидашуда бо танзими шӯсташӯ, ҳаво ва ҳарорати муҳит назорат мешавад. Ин мувозинати дақиқ, навидаи вақти мувофиқро барои фаъолият ва споракунии қамар пӯшида менамояд ва ба деҳқон имконият медиҳад, ки бо сарф кардани камтари қамаркуш, намноки зарарбахшро назорат кунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-خیار-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های خیار با آبیاری قطره‌ای - تصویر 2"/><figcaption>заҳрамезони кӯдакон, бемориҳо, ороғи қатрагӣ, хияр</figcaption></figure>\n\n\n\n\n<h3>Тексоспорус ва Фусариус (Фусариус вилт)</h3><p>Фасули бунафши решаҳо (Фусариус) яке аз бемориҳои ҳаётгиркунандаи хияр аст, ки тавассути замин ба решаҳо ворид мешавад. Ороғи қатрагӣ, ки танҳо қисме аз заминро тар карда, қисмҳои дигарро хушк нигоҳ медорад, хориши қарақушро дар сатҳи замин маҳдуд мекунад. Гарчанде ки ин назорати мутлақ нест, вале суръати паҳншавии уфуқии онро кам мекунад. Мунтазир аст, ки дар парвариши навҳо аз ҳубобҳои муқовиматноки ба фасули бунафш истифода баред ва системаро ороеғи чуқур муайян кунед, то решаи асосӣ дар чуқурии мувофиқ бо тармои кофӣ дар робита бошад. Ин чуқуршавӣ боиси мешавад, ки решаҳо дар минтақаҳои зарбхӯрдаи қарақушҳои сатҳӣ камтар қарор гирӣ.</p>\n<h2>Нуқтаҳои амалӣ барои илтимои ороғ ва идоракунии заҳрмон</h2><ul><li><strong>Ҷудосозии хатҳои ороғ:</strong> Дар деҳони калон, системаро ба зонаҳои мустақил тақсим кунед. Агар шумо зарбхӯрии бемориро дар яке аз зонаҳо мушоҳида карда бошед, метавонед он зонаро аз хати асосӣ ҷудо кунед ва барои он барномаи махсуси заҳркашӣ ё гузаронидани қувваи муқовиматноки ба қарақуш (Дитаро) иҷро кунед, бе он ки тамоми деҳон таъсир дида шавад. Ин усули идоракунии мураҷжаҳат (идоракунии риъ) боиси мешавад, ки аз пахши заҳр ба деҳони солим худдорӣ кунед.</li><li><strong>Пасткунии об:</strong> Ороғи хияр бо оби ланҷ ё чуқурӣ, ба филтрасияи дақиқ (сити 120 ва 150) ниёз дорад. Бастани қатрагунҳо боиси кам шудани фишор ва тағйир ёфтани намунаи ороғ мешавад, ки метавонад ба шиддати замин ва кам шудани бехатарии наботот дар муқобили заҳрмон оварда расонад. Назорати мунтазами филтрҳо зарурӣ аст.</li><li><strong>Идоракунии EC ва pH-и маҳлул:</strong> Хияр барои pH аз 5.5 то 6.2 ҳассос аст. Агар pH-и маҳлул балға равад, ҷалби оҳан ва рӯғъ нисбат ба аввал кам мегардад ва рӯяш заиф мешавад; рӯяи заиф ба ҳадафи асосии даракашҳои барг ва моҳутҳои тиллоӣ мегардад. Назорати ҳафтаними pH-и обҳои оборӣ зарур аст. Танзими сифати об ба маънои доштани рӯяи қавитар дар муқобили бемориҳо аст.</li></ul>\n<h2>Саволҳои мунтазири (FAQ)</h2><ol><li><strong>Оё обори буғатан (drip) метавонад даракашҳои баргро кам кунад?</strong><br>Бале, бевосита. Бо нигоҳ доштани хушкӣ барги ва зиёд намудани муқовимати рӯяш аз роҳи ғизогирии мувозинат, даракашҳо камтар даҳоят доранд. Шумо мумкин аст, ки зарбикунии дифенгериро тавассути системаи буғатан (drip) ворид кунед, то ҷалби заҳрро дар баргҳо осон гардонад.</li><li><strong>Вақти беҳтарин барои зарбикунии орзуи таҳриқ (дотарио) кист аст?</strong><br>Вақти беҳтарин он ҳол аст, ки шумо аз зарари решаҳо ё гург-руҳӣ боварӣ ҳосил кунед. Одатан дар миёнаи росткунии ва пеш аз аъдозаи ҳосил, барои назорати пӯсишҳо. Барои ҳашароти барг, зарбикунии оддӣ боз ҳам самараноктар аст, аммо дотарио барои назорати хушкӣҳо афзалият дорад.</li><li><strong>Оё нӯки тиб барои хияр мувофиқтар аст ё буғатан (drip)?</strong><br>Лентаи микро-камбук (Micro-tube) бар яхои хонаи шишагӣ хеле маъмул аст, зеро пӯшиши равшанро ташкил медиҳад ва дар муқобили таҳшиншудан муқовимати бештар дорад. Аммо барои яхои боғӣ ва фазои кушод, монҷомҳои қатрагӣ (дроплет) бо ҳаҷми 1,6 литр ё болотар, бо назардошти эҳтиёҷи зиёди яхо ба об, беҳтарин вариант мебошад. Интихоби байни ин ду чиз ба <a href="https://navar-abyari.ir/tarzi-intihobi-tasmai-obyari-nuqtagiri-muvofiq/">Усули интихоби дурусти таҷҳизоти обёрӣ</a> вобаста аст.</li></ol>\n<h2>Хулоса</h2><p>Коркардкунӣ ва беҳдошти бемориҳои яхо, аз ҷиҳати мубориза бо ҳашарот хеле васеътар аст; ин як бозикунии кимиёвӣ ва физикӣ мебошад. Истифодаи <strong>обёрӣ бо қатраҳо</strong> ва лентаи микро-камбук ба шумо имконияти назорати беҳтари обро медиҳад, то намии рӯданоро оптимизатсия кунед ва парҳези сарбелани спораҳои қурроғҳо пешгирӣ намоед. Бо истифода аз дитаро шумо метавонед мухофимҳоро (антагонистҳо)-ро бевосита ба рӯданоҳо расонед ва бо назорати pH ва EC, бехатарии растаниро дар муқобили баррондандани баргҳо ҳифз кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-خیار-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های خیار با آبیاری قطره‌ای - تصویر 3"/><figcaption>crop pests diseases drip irrigation яхои яхвор</figcaption></figure>\n<p>Намоён бошед, ки системаи оборидани шумо танҳо васеи интиқоли об нест, балки системаи идоракунии солимии кишаст. Бо баҳс гирифтани фарқиятҳои минтақавӣ, омӯзиши манбаъҳои ихтисосии дигар монанди <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%aa%d9%88%d8%aa-%d9%81%d8%b1%d9%86%da%af%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми ҳосили саҳлуба дар гектар: омили ва усулҳои афзоиш</a> ё дигар киштҳои иловагӣ метавонад дар давраи корӣ ва идоракунии умумии кӯшор ба шумо кӯмак расонад. Ҳамин тавр санҷиши <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%ac%d9%88-%d8%a8%d9%87%d8%a7%d8%b1%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми ҳосили ҷави баҳорӣ дар гектар</a> барои ташхиси нақшаи киштҳои занҷирӣ фоиданок аст. Барои дастёби иттилооти бештар дар бораи <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d9%be%db%8c%d8%a7%d8%b2%da%86%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми ҳосили пиязк дар гектар</a> шумо метавонед дастурҳои мо-ро хонед. Дар охир, як системаи ободиши солим, ним роҳ ба тарафи як ҳосили бодиринги бидуни камбудӣ аст.</p>\n<p><strong>Матлаби алоқаманд:</strong> Ҳаҷми ҳосили сабзи ҳашмӣ (тӯт-фаширӣ) дар ҳектар: омили ва роҳҳои зиёд кардан <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d9%be%db%8c%d8%a7%d8%b2%da%86%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми ҳосили сабзӣ (сӯмӣ) дар ҳектар: роҳнамои муфассал + нуқтаҳои зиёд кардан</a>، <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%ac%d9%88-%d8%a8%d9%87%d8%a7%d8%b1%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми ҳосили гандуми баҳорӣ дар ҳектар: чораҳои амалӣ ва нав</a>، <a href="https://navar-abyari.ir/tarzi-intihobi-tasmai-obyari-nuqtagiri-muvofiq/">Тартиби интихоби таҷҳизоти абоберии қутрагӣ (каппӣ) барои муваффақият</a></p>','Вобастагии беморӣ ва зараррасонандаҳои кукуруз бо обёрӣ ноқтаталавӣ: Роҳҳои пешгирии идоракунӣ','Обори чанпаки (қатрагӣ) на танҳо манбаи таъмин намудани намнокӣ аст, балки нақши калидӣ дар пешгирӣ аз паҳншавии бемориҳои хокза ва кам кардани ниёз ба доруҳои зараррасон дорад. Дар ин мақола мо ба таҳлили ихтисосии зараррасонҳо ва бемориҳои оддии хияр дар таъсироти обори чанпаки (қатрагӣ) ва системаи нип (ривер) мепардозем.','publish','closed','closed','zarardarsuvarak-kukuruz-obari-noqatatalavi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
