INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима</h2>\n<p>Кунҷид яке аз муҳимтарин рӯғонӣҳои ҷаҳон аст, ки дар бисёр минтақаҳои хушк ва нимхушк партоб мешавад. Яке аз чаллаҳои асосии деҳқонон, идора кардани <strong>зараррезҳо ва бемориҳои кунҷид бо обёрӣ бо тамғаҳои</strong> аст. Агарчун системаҳои замониравии обёрӣ, ба монанди тамғаҳо ва набутиб, нақш доранд дар сармоиҳо, вале онҳо метавонанд шароитҳои муҳитро чунин тағйир диҳанд, ки ба патогенҳо ва зараррезҳо таъсир расонанд. Дар ин бахш, назари умумӣ ба робита байни режими обёрӣ ва саломатии растании кунҷид меандозем. Кунҷид растание аст ба тағйиротҳои микроклимат, ва ҳар гуна нисбат дар миқдори об ва намии хок метавонад ба таври мустақим ба муқовимати растанӣ бар зидди муҳлисони бегона таъсир расонад. Бинобар ин, фаҳмиши амиқ аз механизаҳои рушд ва ниёзҳои растанӣ, қадами аввал барои идоракунии деҳқононаи муваффақ аст. Деҳқонон бояд донист, ки обёрӣ танҳо як марҳилаи таъмини моддаҳои ғизоӣ нест, балки қисме аз стратегии муҳофизоти растанӣ зидди омилҳои бемориза аст.</p>\n<p>Бемориҳои фити, виротӣ ва занбӯрӣ ва ҳамчунин зараррезҳои заррин, зердак ва чигҳиш метавонанд, дар сурати идоракунии нодуруст, ҳосилро то 40 фоиз кам карданд. Истифодаи обёрӣ маҳаллӣ, имконияти партобҳои дақиқтари маҳлул ва кам кардани намии нисбии баргҳоро фароҳам меоварад, ки ин омилҳо дар назорати бемориҳои гурзидани сабзи ва хози хеле самаранок аст. Барои намуна, кам кардани тамоси мустақими об бо сари растанӣ, муҳити рушди муносиб барои занбӯрҳои гурзиданро ба таври ҷиддӣ маҳдуд мекунад. Дар пасо, тафсилоти ин равандҳо ва роҳҳои амалӣ барои беҳтар кардани шабакаи обёрӣ барои саломатии растанӣ баррасӣ мешавад.</p>\n\n<h2>Таъсири обёрӣ бо тамғаҳо ба паҳншавии бемориҳо</h2>\n<h3>Кам шудани бемориҳои сарчашмаи занбӯрӣ ва бактериявӣ</h3>\n<p>Яке аз мувоҷибҳои асосии ороии тамлӣ кам шудани тамоси мустақими об бо баргҳост. Бемориҳо, монанди куфтани сиёҳи сабук (Alternaria) ва паҳншавии сафед, дар сурати баланд будани намии сатҳи барг тезтар паҳн мешаванд. Дар системаи тамлӣ об бевосита дар атрофи реша тақсим мешавад, ки боиси кам шудани паҳншавии бемориҳоест, ки тавассути ҳаво паҳн мешаванд. Бо вуҷуди ин, қарчҳои зеризаминӣ, монанди фусарий ва питиум, метавонанд тавассути оби ифношуда ба боғзор расонда шаванд; бинобар ин, сифати оби манбаъ муҳим аст. Истифодаи манбаҳои об тоза ва нест кардани ғадудҳо ва намакҳои зарарнок пеш аз воридшавӣ ба шабака, аз ҳадафҳои асосӣ аст. Инчунин, назорати pH-и об метавонад аз рӯиҳои бактерияҳои зараровар дар лӯлаҳо ва тамлчканҳо пешгирӣ кунад ва саломатии решаҳоро таъмин намояд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-کنجد-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های کنجد با آبیاری قطره‌ای - تصویر 1"/><figcaption>зарагардони ҳашарон ва бемориҳои ҳосил ороии тамлӣ кунҷид</figcaption></figure>\n\n<h3>Идоракунии намии хок ва шароити фишор</h3>\n<p>Кунҷид намояндае аз ҳосилоти деҳот аст, ки ба таъсири норасидии об баъдан тобовар аст, аммо ороии зиёдатӣ боиси парокандагии гулҳо ва зиёд шудани таъсири кунҷишавӣ мешавад. Системаҳои тамлӣ имконро месозанд, ки дозаи ороиро вобаста ба тақсимоти дақиқ танзим кунед. Ин дақиқӣ боиси мусоидан намуди намии хок дар замири реша мешавад ва ҷисми наметавонад дар сатҳи пасттари фишор бошад, ки худ сабаби зиёд шудани муқовимати ба даст овардашуда (Induced Resistance) нисбат ба зараррасониҳо мешавад. Назорати мунтазами намии хок бо истифода аз сенсорҳои рақамӣ метавонад аз ҷазира аз ҳадди оптималӣ пешгирӣ кунад. Ҷисм, ки дар зери фишори об оварда шудааст, ифодаи шакро кам мекунад ва сабукиҳои боэътимотпечашаро истеҳсол мекунад, ки омода будани зараррасониҳо ифода мекунанд. Бином бар ин, мувозинат дар ороии тамлӣ қабати эҳтиётоти биологӣ барои ҷисми мутобиқсозӣ мекунад.</p>\n\n<h2>Зараррасониҳо-ҳашарон ва алоқаашон бо системаи ороӣ</h2>\n<h3>Танзими шитон ва ҳашарон тавассути идоракунии намӣ</h3>\n<p>Шитҳо ва гурдагиҳои сурх одатан дар шароити гарм ва хушк ё дар ҳолатҳои стресси бутавон фаъолтар мешаванд. Сепатсири танқати доимӣ метавонад аз стресси камии об пешگیری кунад, аммо дар сурати тағйирёти шадид, бутавон бозорпандар мешавад. Инчунин, кам шудани намии нисбии сатҳи баргҳо тавассути системаи танқатӣ метавонад муҳитро барои баъзе муҳолифони табии муносибтар сабт кунад. Бо вуҷуди ин, қубадҳои паҳлӯги дарахтӣ аз сепатсири танқатӣ (напуллу шудани пурраи бофтаҳо) метавонад паноҳгоҳи мувофиқ барои лаҳзҳои баъзе ҳашароти хокӣ, ба монанди занбӯри хонак, гардад. Лозим аст, ки боқимондаҳои дарахтӣ дуруст идора шаванд, то аз ҷамъ шудани зараррасонҳо пешگیری шавад. Инчунин, диққат ба ғаллаҳои ҳамроҳ (Companion Plants), ки зараррасонҳоро ба сӯи худ ҷазб мекунанд, метавонад аз ҳамлаи онҳо ба кунҷубод пешگیری кунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-کنجد-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های کنجد با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation کنجد</figcaption></figure>\n\n<h3>Кормоки абрешум ва ҳашароти хокӣ</h3>\n<p>Зимне, ки системаи танқатӣ одатан бо истифода аз лӯлаҳо дар зерозӣ тавсиф мекунад, имкони баъзе зараррасонҳои хокӣ тавассути роҳи ҳароратшик (Fertigation) вуҷуд дорад. Ин роҳ, баръакси баъзе зараррасонҳои сатҳӣ, саммимандӣ дар решаи ҷинсиро зиёд мекунад. Барои намуна, кормоки хокии кунҷубод метавонад бо истифода аз биотикҳо, ки тавассути системаи сепатсир оварда мешаванд, идора шавад. Диққат ба консентратсия ва вақти овардани ин моддаҳо омили муҳим дар муваффақии ғаллакунӣ аст. Истифодаи филтрҳои мувофиқ барои пешгирии хӯрашӣ аз ғалабаҳо бо заррарҳои зараррасон, яке аз заруиятҳои техникии ин системаҳо аст. Идоракунии дурусти ин раванд метавонад зарурияти истифодаи зараррасонҳои химиявии системӣ-ро кам кунад ва маҳсули бехатартарро ба бозор диҳад.</p>\n\n<h2>Нуқтаҳои амалӣ барои кишлоҳҳо</h2>\n<ul>\n<li><strong>Фильтрасияни дақиқ:</strong> Истинофармӯи фильтраҳои часпкунанда ва шабакаҳои мувофиқ барои пешгирии часпидани бурҳо ва дохил шудани зарраҳои ифношуда ба шабакаи обёрӣ, ки метавонанд боиси гирифтигии маҳаллӣ ва поришани реша гарданд. Нигоҳдории мунтазами филтраҳо вобаста ба миқдори афрудани оби манбаъ зарур аст.</li>\n<li><strong>Гизокунии мувозинатпазир бо усули паҳш:</strong> Истинофнабудани моддаҳои органикии нопарҳезӣ, ки метавонанд рушди бактерияҳои зарароварро дар шабака меҳвотаранд. аз кудҳои ҳалшуда ва санҷидашуда истифода барӣ ва pH-и маҳлулро пеш аз инъикс дар система ба мадони мувофиқ танзим кунед, то ҳалшавии моддаҳоро пешгирӣ намоед.</li>\n<li><strong>Моноитинги деҳқоронӣ:</strong> Бо вуҷуди обёрӣ бо усули қатравӣ, боздиди мунтазим аз минтақаи решаҳо барои диیدن аз аломатҳои аҳмос иллат ва афтидани барг зарур аст. Санҷиши ранги дарахту барг метавонад нишонаи аввалин барои муайян кардани ноқисӣ ё зиёдшавии моддаҳои равғаннокунанда бошад.</li>\n<li><strong>Алмунбазарӣ (куръшавии ғаллӣ):</strong> Пас аз ғаллӣ ё ҳура дар як деҳқоронӣ кӯрби каннобиро накунод. Хондани дастурашномои <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%b4%d9%88%db%8c%d8%af-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/" title="مقدار بذر شوید در هکتار">Миқдори бовари савори дар гектар</a> Имкон медиҳад, ки ба нақшакунии беҳтари давраи кӯбист карданд. гуногунии арзы мусбад кӯбистро боз донанд.</li>\n</ul>\n\n<h2>Барзҳои муайян дар системаҳои нарми нафиш</h2>\n<p>Кӯшҳои бисёре аз кунҷири барои кӯши кунҷири <strong>нарми нафиш</strong> истифода мебаранд. Мушкилоти маъмул дар ин системаҳо ишораи хурду корҳиши аз ҷамъшавии об дар нуқтаҳои муайянро ифода мекунад. Пайгир кардани фишор дар лӯлаҳои асосӣ ва иловагӣ муҳим аст. Инчунин, таҳияи дурусти шабака барои пешгирии ҷамъшавии об дар қимати қанали парваришӣ тавсия дода мешавад. Фаҳмиши амиқ аз <a href="https://navar-abyari.ir/%d9%85%d8%b4%d8%ae%d8%b5%d8%a7%d8%aa-%d9%81%d9%86%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c/" title="مشخصات فنی نوار تیپ آبیاری">маъиёрҳои фанни системаи нарми нафиш</a> метавонад ба мушкилиҳои гидроликӣ ва дар натиҷа стресси бозгашт ба беморӣ оварда ба ҳуқуқ кунанд. Интихоби нафиш бо ҳарфи мувофиқ, таъсири мустақиме бар сифати тақсими об дар дарозии қатор мегардонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-کنجد-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های کنجد با آبیاری قطره‌ای - تصویر 3"/><figcaption>crop pests diseases drip irrigation kinjir</figcaption></figure>\n\n\n<h2>Саволҳои маъмулӣ (FAQ)</h2>\n<ol>\n<li><strong>Оё осевишди қатқатӣ метавонад ба пӯсидагии решаҳои кунҷубод оварда расонад?</strong> Бале, агар системаи рафконӣ заиф бошад ё фосилаҳои осевиш номутобиқ бошад, намии давомвӣ метавонад боиси хӯшакҳои занбӯрӯҳӣ гардад. Тadbироти дурусти вақт ва дозаи осевиш калиди ҳалли ин мушкилост.</li>\n<li><strong>Оё метавон маводҳои занбӯрӯҳӣ-бардошандагонро тавассути қатқатӣ инъикт кард?</strong> Бале, аммо бояд аз шаклҳои махсуси фертисатсия истифода бурд, то аз хам шудани дарилҳо пешгирӣ карда шавад. Ин усул самаранокии баланд дар назорати бемориҳои занбӯрӯҳии хокӣ дорад.</li>\n<li><strong>Беҳтарин вақти муайян кардани зараррасонҳо дар боғзорҳои қатқатӣ кӣ аст?</strong> Баъди барфаришҳои борон ё дар фавсҳои тар, назорати биниш аз баргҳои поёнӣ ва сабулонҳо иштироки махсус дорад. Инчунин пеш аз оғози давраи гулафшонӣ, ҳассосияти растаниҳо ба зараррасонҳо зиёд мешавад.</li>\n</ol>\n\n<h2>Хулоса</h2>\n<p>Боздори <strong>Зарароварон ва бемориҳои абрешак дар озиришдиришӣ тори озув</strong> бе ташаккули як қарорадди чандири доронӣ аст. Азбаски системҳои озиришдириши мушаххас тағйироти микроклиматии саҳроҳоро ба вуҷуд меоранд, кишткун бояд ҳамзамон ба сифати об, санитарии шабака ва даври кишт диққат диҳад. Истифодаи маълумоти илмӣ ва назорати давомдӯда, калиди баландбурдиши натиҷаҳо ва коҳиш додани зарари кешти абрешак дар шартҳои камобӣ аст. Барои беҳ истифода бурдани системҳои муосири озиришдириш, омӯзиши манбаҳои ихтисосӣ, масалан <a href="https://navar-abyari.ir/%d8%b1%d9%88%d8%b4%d9%87%d8%a7%db%8c-%d9%85%d8%af%d8%b1%d9%86-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%b2%d9%85%db%8c%d9%86-%da%a9%d8%b4%d8%a7%d9%88%d8%b1%d8%b2%db%8c/" title="روش‌های مدرن آبیاری زمین‌های کشاورزی">Усулҳои муосири озиришдириши заминҳои кешоварӣ</a> пешниҳод карда мешавад. Инчунин, барномакунии дақиқи кеш кушодан бо даромаднокӣ <a href="https://navar-abyari.ir/wheat-irrigation-yield-per-hectare-comprehensive-guide/" title="wheat irrigation yield per hectare comprehensive guide">намоишдиҳиши умумии озиришдириши ҷав</a> мусоидат ба оптимизатсияи манбаҳои минтақавӣ мекунад. Дар ниҳоят, гирефтуравонии дониши техникии озиришдириш бо принсипҳои кишоварӣ ба маҳсулоти сифатони баланд ва муқовимати зиёдтар нисбати омили беморибурӣ оварда мерасонад.</p>\n\n<p><strong>Мавзӯиҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/%D9%86%DA%AF%D9%87%D8%AF%D8%A7%D8%B1%DB%8C-%D9%88-%D9%85%D8%AF%DB%8C%D8%B1%DB%8C%D8%AA-%D9%86%D9%88%D8%A7%D8%B1-%D8%A2%D8%A8%DB%8C%D8%A7%D8%B1%DB%8C-%D8%AA%DB%8C%D9%BE/">Нигоҳубинӣ ва идоракунии нақобҳои обории типи</a></p>','Хаставҳои зери ҳимс ва бемориҳои онҳо бо риёи қабулашуда','Дар ин мақола мо ба таҳлили таъсироти мусбат ва манфии обёрории поқтам (дрийп-обёрӣ) ба паҳншавии зараррасонҳо ва бемориҳои кунҷит мешавем. Роҳҳои амалӣ барои кам кардани сатҳи зарари расида ва афзудани саломатии ниҳоҷ бар асоси идоракунии дақиқи манбаъҳо пешниҳод мекунанд.','publish','closed','closed','hims-pests-and-diseases-with-drip-irrigation',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
