INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>مقدمة: الأهمية الحيوية لتوزيع الشريط القابل للري في حقول الحمص</h2>\n<p>يعتبر الحمص من البقوليات الرئيسية في الزراعة الإيرانية، وبسبب حساسيته النسبية لإدارة الماء والتربة، فهو يحتاج إلى اهتمام خاص في تخطيط أنظمة الري. أحد أهم المعايير الفنية التي يجب أن يكون المزارعون على دراية بها، <strong>مسافة شريط الري في زراعة الحمص</strong> هو. يرتبط هذا التباعد مباشرةً بأنماط الزراعة وعمق نمو الجذور ومعدل التبخر من سطح التربة. أي خطأ في ضبط المسافة بين الصفوف وشريط الري قد يؤدي إلى إجهاد الماء للجذور، ونمو غير متماثل للنباتات، وانخفاض في المحصول النهائي في نهاية المطاف.</p>\n<p>في هذه المقالة، سنتناول التفاصيل الفنية المتعلقة بتخطيط الصفوف (Row Layout) للحمص وطريقة وضع شرائط الري في هذا النظام. هدفنا هو تقديم دليل عملي يمكن للمزارعين من خلاله اتخاذ أفضل القرارات بناءً على الظروف المناخية ونوع التربة لديهم. الإلمام بمبادئ <a href="https://navar-abyari.ir/type-irrigation-tape-installation-method/">طرق تركيب شريط الري</a> في المحاصيل الأخرى يمكن أن يوفر منظورًا مكملًا لفهم تحديات الحمص بشكل أفضل.</p>\n\n\n\n<h2>تحليل تقني لأنماط الزراعة وترسيب جذور الحمص</h2>\n<p>لتحديد المسافة المناسبة لخط الري، يجب مراعاة أولاً بنية جذور الحبة. جذور الحبة سطحية؛ فحوالي 70 إلى 80٪ من الكتلة الجذرية توجد في أول 30 سم من التربة. لذلك، يجب وضع خط الري على عمق الحلقي هذا بالضبط. إذا كانت مسافة المزارع كبيرة جداً، فإن تركيب خط على كل صنف سيؤدي إلى جفاف المناطق بين الجذور المجاورة، مما يسبب إجهاداً في ذروة درجات الحرارة.</p>\n<h3>المعايير الذهبية لمسافة الصفوف</h3>\n<ul>\n<li><strong>البذر العشوائي:</strong> عادةً، يُصعب استخدام خط الري بسبب توزيع الجذور غير المنتظم، وتُركب الخطوط غالباً على شكل صفوف (مثلاً كل 40 سم).</li>\n<li><strong>البذر الصفوف باستخدام المسطرة:</strong> أفضل طريقة للحبة هي مسافة صفوية بين 45 إلى 60 سم. في هذا الوضع، يُوصى بخط ري مركزي واحد بين صفين، أو خطي ري مثبتين في قاعوع الحياك.</li>\n<li><strong>التأثير على الكثافة:</strong> زيادة كثافة النبات في المتر مربع الواحد تحتاج إلى مسافة أقل بين الخطوط لتنشيط كامل الإمكانات للنمو التغطي.</li>\n</ul>\n<p>عندما نفحص <a href="https://navar-abyari.ir/qadamhoi-nasbi-navori-tip/">مراحل تركيب شريط الري بالتنقيط</a> سننظر، سنشوف اهميه الاستقرار الميكانيكي للشريط على مدى الموسم الزراعي، لا سيما اثناء عمليات رش المبيدات وقت الغرس، عاليه جدا. العدس بسبب حبوبه الصغيره، ممكن يصير تحدٍ خاص على ماسك البذور في بعض انظمة الدقه العاليه للغرس؛ عشان كذا، مسافه شريط الري من خط الغرس (غالباً من 10 الى 15 سم جانبياً) لازم تكون بحيث ما تتداخل مع ميكانيكيه الغرس.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-عدس-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت عدس: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop عدس</figcaption></figure>\n\n\n\n<h2>تأثير مسافه شريط الري على الpathology وامراض الجذور</h2>\n<p>واحد من الاسباب الخافيه بموضوع مسافه شريط الري بزراعه العدس، هو اداره الرطوبه ومنع الامراض اللي تأكل الجذور. تعفن الجذور (Root Rot) يصير شائع بأحوال الري الزايد عن اللزومي بالشرايط اللي مسافتهم بعيد بعض من بعض وبمعدلات تدفق غلط. العدس حساس للراكمه الميه منطقه الجذور. إذا مسافه الشرايط المتوازيه تكون قريبه اوي، بالتربيه الطينيه اختراق الرطوبه للطبقات السفليه بطيء، والرطوبه تتجمع بالشرايط الجانبيه.</p>\n<h3>نموذج الترتيب المقترح للتربيه الثقيله والسهله</h3>\n<ol>\n<li><strong>التربيه السهله والرمليه:</strong> في هذه التربة، يتسرب الري رأسياً بسرعة. يوصى باستخدام شريط ري بمسافة صفوف 50 سم وبمعدل تدفق مناسب. يعمل نظام «الصف المزدوج» مع شريط مركزي بين كل صفين بكفاءة عالية جداً في هذه التربة.</li>\n<li><strong>التربة الطينية الثقيلة:</strong> في هذه الظروف، يوجد خطر اغراق في شريط الري. من الأفضل زيادة المسافة بين خطوط الزراعة قليلاً (حتى 65 سم) ووضع شرائح الري النقطي بدلاً من الري المباشر في شرائط أوسع، حتى لا يتشكل جبه المبلل (Wetting Front) بسرعة ويتسرب إلى طبقات أعمق.</li>\n</ol>\n<p>تشابه سلوك الري في الخضروات الأخرى قد يكون مفيداً أيضاً؛ مثلاً في <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%aa%d8%b1%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">زراعة الخضروات الورقية والخضار</a> التي لها جذور سطحية، حيث أن مبادئ مسافات شريطات الري النقطي مشابهة جداً للحمص. في كلا الحالتين، الهدف الرئيسي هو تغطية شريط الجذور الفعالة بالكامل دون تكوين كتل رطوبة.</p>\n\n\n\n<h2>نصائح عملية لتحسين مسافات شريطات الري النقطي</h2>\n<p>التطبيق الفني في المزرعة قد يكون مرافقاً أحياناً بتحديات ميدانية. فيما يلي أهم النصائح التطبيقية للمزارعين الحمصيين:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-عدس-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت عدس: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>تباعد شريط الري بالتنقيط، تخطيط الصفوف، المحصول، الحمص</figcaption></figure>\n<h3>توازن بين التكلفة والعائد</h3>\n<p>كلما زادت المسافة بين الأشرطة، قلّت طول الشريط المطلوب لكل هكتار وانخفضت تكلفة الإعداد المسبق للزراعة. لكن قد يكون انخفاض التكلفة هذا غير قابل للتعويض بسبب انخفاض المحصول بنسبة ٢٠ إلى ٣٠٪. في <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%da%a9%d8%af%d9%88-%d8%a2%d8%ac%db%8c%d9%84%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">الدراسات المرتبطة بزراعة القرع والخضروات</a> رُصد أيضاً أن تحسين تباعد الأشرطة يحدد النقطة المثلى بين تكلفة الخضروات والعائد النهائي. بالنسبة للحمص، يُوصى باعتماد نمط «شريطين متوازيين بمسافة ٤٥ سنتيمتراً» كنقطة انطلاق.</p>\n<h3>مراقبة عمق دفن الشريط</h3>\n<p>لا يمثل تباعد شريط التنقيط عرضياً المتغير الوحيد؛ بل يلعب عمق الدفن دوراً أيضاً. إذا وُضع شريط التنقيط على سطح التربة، تزداد تبخر الرطوبة وتدهور الشريط بسبب الفئران والحشرات. يجب وضع شريط التنقيط على عمق يتراوح بين ١٠ و١٥ سنتيمتراً في التربة، على نفس مستوى عقد جذور الحمص الرئيسية.</p>\n\n<h2>الرد على الأسئلة الشائعة (FAQ)</h2>\n<h3>۱. هل نستطيع استخدام شريط تبخيري في منتصف المسافات بين الصفوف بدلاً من لصقه بالقرب من الجذور؟</h3>\n<p>نعم، في المسافات بين الصفوف التي تتجاوز ۶۰ سم، قد يكون وضع شريط مركزي منطقياً. ولكن في المسافات القياسية من ۴۵ إلى ۵۰ سم، يوفر لصق الشريط على كل صف أو الشرائح المزدوجة تغطية أفضل للجذور.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-عدس-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت عدس: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>drip tape spacing row layout crop عدس</figcaption></figure>\n<h3>۲. ما دور نوع التربة في تغيير مسافة الشريط؟</h3>\n<p>في التربة الطينية، يجب أن تكون المسافات أوسع قليلاً (۵۵-۶۵ سم) حتى تصل الرطوبة بسرعة إلى الجذور ولا يتشكل تجمع مائي. في التربة الرملية، يمكن أن تكون المسافات أضيق (۴۵-۵۰ سم)، لأن الجذور تنتشر أكثر للوصول إلى الماء.</p>\n<h3>۳. هل ترتبط مسافة شريط الري بالتنقيط بنقصان المياه في المنطقة؟</h3>\n<p>في المناطق شحيحة المياه، يؤدي استخدام مسافات أقرب بين الشرائط إلى إنشاء شريط رطوبة زجاجي حول الجذور ويزيد من كفاءة المياه، ولكن نظراً لتكلفة الاستثمار، يجب إجراء حسابات اقتصادية.</p>\n\n<h2>الخلاصة والاستنتاج</h2>\n<p>الموضوع <strong>مسافة شريط الري بالتنقيط في زراعة العدس</strong> هي معلم يُقاس مخصصا لكل منطقة (Site-specific) وتعتمد على عدة عوامل. ولكن بشكل عام، الالتزام بمسافة تتراوح بين 45 و60 سم بين الصفوف، مع تثبيت شريط الري بالتنقيط في منطقة جذور نشطة، يمكن أن يؤدي إلى تحسين ملحوظ في جودة الحبوب وتقليل استهلاك المياه. الفلاحون الأكثر نجاحا هم من يتبنون نموذج "الصف المزدوج" أو "الشريط المركزي" بناءً على نوع التربة والمناخ في منطقتهم، مع إجراء اختبارات محلية دقيقة. ومع دراسات إضافية مثل <a href="https://navar-abyari.ir/mikorit-khomi-yufa-hamadoni-dar-hektar/">استخدام الميكوريزا في النبات</a> والتحكم في كثافة الزراعة، يمكن الاستفادة الكاملة من أنظمة الري بالتنقيط للعدس.</p>','مسافة صف التربة في زراعة الحمص: المعايير الموصى بها','اختيار مسافة مناسب لنظام الري بالتنقيط في زراعة الحمص يكون لها تاثير مباشر على تعفن الجذور، والعائد الاقتصادي، وإدارة المياه. في هذه المقالة من navar-abyari.ir، نناقش المعايير الذهبية لتنسيق الصفوف وتثبيت انابيب الري بالتنقيط.','publish','closed','closed','distance-row-fava-bean-planting-standards',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
