INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти ҳаётии ҷойгиршавии нӯраи типӣ дар бӯстонҳои нохӯд</h2>\n<p>Ноҳӯд яке аз ҳосили асосии ҳунармандии кишоварии Эрон аст, ки барои эҳтиётоти нисбат ба идоракунии об ва хок ба диққати махсус дар бунёдидеҳии системаҳои оборӣ ниёз дорад. Яке аз муҳимтарин параметрҳои техникӣ, ки ба бӯстонҳо бояд бо он шинос бошанд, <strong>Фосяи нӯраи типӣ дар зери ноҳӯд</strong> мебошад. Ин фосагузорӣ бевосита бо нақшаи куднокунӣ, амиқии рушди решаҳо ва миқдори буғушавӣ аз сатҳи хок алоқаманд аст. Танзими нодуруст дар фоса байни сатрҳо ва нӯраи типӣ метавонад боиси таҳаммулоти обӣ барои решаҳо, рушди асимметрӣи бутаҳо ва дар натиҷа камшавии ҳосили ниҳоӣ гардад.</p>\n<p>Дар ин мақола, мо ба таҳлили мукассаи маълумоти техникӣ дар бораи ҷойгиршавии сатраи (Row Layout) ноҳӯд ва тарзи ҷойгиршавии нӯраҳои типӣ дар ин система муроҷиат мекунем. Ҳадафи мо пешниҳоди роҳнамои амалӣ мебошад, ки кишоварон тавассути шароити иқлимӣ ва намуди хоки худ қарори беҳтаринро гиранд. Шиносӣ бо принсипҳои <a href="https://navar-abyari.ir/type-irrigation-tape-installation-method/">Усулҳои насби нӯраи типӣ</a> дар дигар кӯдаҳо низ метавонад назарокии иловагӣ барои фаҳми беҳтари мушкилоти ноҳӯд бошад.</p>\n\n\n\n<h2>Таҳлили техникӣ нақшаи куднокунӣ ва ҷойгиршавии решаи ноҳӯд</h2>\n<p>Барои муайян кардани масофаи мувофиқи ришта (лент), аввал бояд анатомияи решаҳои лубиаро ба назар гирифт. Решаҳои лубиа чуқурӣ нест; тақрибан аз 70 то 80 фоизи ҷисми решаҳо дар 30 сантиметри аввали хурак мавоҷиҷ мекунад. Бинобар ин, риштаи лент бояд маҳз дар ин чуқурӣ ҷойгир шавад. Агар масофа байни сатҳҳои кишт хеле зиёд бошад, ҳатто бо часпондани ришта ба ҳар сатҳ, минтақаҳои хушк байни решаҳои ҳамсоя пайдо мешавад, ки дар лаҳзаҳои баландшудани ҳарорати ҳаво ба стресс оҳанг мерезад.</p>\n<h3>Мабниҳои тиллоии масофаи сатҳҳо (Row Spacing)</h3>\n<ul>\n<li><strong>Кишти пехт ва паҳншавии бӯёнҳо (Broadcast):</strong> Одатан дар ин усул истифодаи риштаи лент бо сабаби тақсимоти номуносибати решаҳо душвортар аст ва риштаҳо одатан ба шакли сатҳӣ (масалан, ҳар 40 сантиметр) насб карда мешаванд.</li>\n<li><strong>Кишти сатҳӣ бо чойқумонҳо:</strong> Беҳтарин ҳолат барои лубиа масофаи сатҳӣ байни 45 то 60 сантиметр аст. Дар ин ҳолат, як риштаи лент марказии байни ду сатҳ ё ду риштаи лент часпида ба қафасҳои зарфҳои кишт тавсия дода мешавад.</li>\n<li><strong>Таъсири ба зичии ҳайвототӣ:</strong> Зиёд кардани зичии ҳайвототӣ дар ҳар метри мураббаъ ба масофаи камтар байни риштаҳо ниёз дорад, то тамоми потенсиали афзоиши пӯши хурак фаъол шавад.</li>\n</ul>\n<p>Ҳангоми ки ба таҳқиқот <a href="https://navar-abyari.ir/qadamhoi-nasbi-navori-tip/">марҳилаҳои насби нави дорои пор</a> мебароем, дида мерасем, ки устувии механикии нав дар давоми мавсими афруиш, махсусан ҳангоми амалиётҳои паҳнкунии тохӯр (бод) ҳангоми кӯрпуронӣ, муҳим аст. Ҷуворӣ бо сабаби дохонҳои хурдаш дар баъзи системаҳои кӯрпурони дақиқ метавонад барои қисмҳои тохӯр (бод) мушкиле эҷод кунад; бинобар ин, масофаи нав дар сатҳи кӯрпуронӣ (одатан 10 то 15 см паҳлӯвӣ) бояд ба таври бои муосирашудани техникӣ бо кӯрпуронӣ таъсир нарасад муайян карда шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-عدس-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت عدس: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>масофаи нави дорои пор, чидани сатҳҳо, ҷуворӣ</figcaption></figure>\n\n\n\n<h2>Таъсири масофаи нави дорои пор ба патология ва бемориҳои решаӣ</h2>\n<p>Яке аз сабабҳои пинҳонӣ дар масъалаи масофаи нави дорои пор дар кӯрпурони ҷуворӣ, идоракунии намнокӣ ва пешгирии бемориҳои таҳшинкунанда аст. Рӯиши ресма (Root Rot) дар шароити обёрӣи зиёд дар навҳо бо масофаҳои бузург ва ҷараёни ноҳис, маъмул аст. Ҷуворӣ нисбат ба ҷамъшавии об дар минтақаи ресма ҳассос аст. Агар масофаи навҳои параллелӣ зиёда кушод бошад, дар хокҳои гилӣ нозукшавии намнокӣ ба қабатҳои поёнӣ суст аст ва намнокӣ дар навҳои паҳлӯвӣ ҷамъ мешавад.</p>\n<h3>Намуди чидани тавсияшуда барои хокҳои вазнин ва сабук</h3>\n<ol>\n<li><strong>Хокҳои сабук ва гарма (сандукӣ):</strong> Дар ин хуракҳо, ғаволи оббори амудӣ зуд аст. Тавсия карда мешавад, ки аз наварҳое истифода баред, ки фосилаи онҳо байни сатрҳо 50 сантиметр ва анор олу одагӣ муносиб бошад. Ҷойгиршавии «сатри дукарда» бо як навар марказӣ байни ҳар ду сатр дар ин хуракҳо самаранокии хеле хуб дорад.</li>\n<li><strong>Хуракҳои гилӣ ва вазнин:</strong> Дар ин шартҳо, хатари обгирӣ дар навор вуҷуд дорад. Беҳтар аст, ки фосила байни хатҳои ғотӣ каме зиёд карда шавад (то 65 сантиметр) ва наварҳои тип ба ҷои хатҳои мустақим, дар наворҳои пурнамо ҷойгир шаванд, то намӣ ба суръати хушк шудан (Wetting Front) тарзи пайдо накунад ва ба қабатҳои чуқуртар ғаволе.</li>\n</ol>\n<p>Машоҳидаи рафтори обборӣ дар сабзавоти дигар низ метавонад роҳкунанда бошад; масалан дар <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%aa%d8%b1%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">кории сабзию нон</a> ки решаҳои сатҳӣ доранд, принсипи фосилагӣ дар наварҳои тип хеле монанди нӯст мебошад. Дар ҳарду ҳолат, мақсади асосӣ пӯшиши пурраи навари решаҳои фаъол бе эҷоди кӯмакҳои намӣ аст.</p>\n\n\n\n<h2>Нуқтаҳои амалӣ барои беҳтар кардани фосилаи наварҳои тип</h2>\n<p>Ҷорӣ кардани фаннӣ дар майдон вақтан бо мушкилоти майдонӣ ҳамроҳ шуда метавонад. Дар зер муҳимтарин нуқтаҳои иҷроя барои деҳқонони нӯст оварда шудаанд:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-عدس-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت عدس: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>Интервали ҷойгиршавии ришта, тарҳбандии қатор, парвариши лӯбиё</figcaption></figure>\n<h3>Мувозунати байни харҷҳо ва ҳосилот</h3>\n<p>Чӣ қадар фосилаи миёни риштаҳо дуртар бошад, дарозии риштаи зарурӣ барои ҳар гектар камтар шуда, харҷи асосии парвариш коҳиш меёбад. Аммо ин коҳиши харҷ бо камшавии 20 то 30 фоизии ҳосил, ки ҷӣбозӣ намумонад, вобастагии ғайриимкон пайдо мекунад. Дар <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%da%a9%d8%af%d9%88-%d8%a2%d8%ac%db%8c%d9%84%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Таҳқиқоти вобаста ба парвариши хурму сабзавот</a> Низ мушоҳида шудааст, ки беҳтарсозии фосилаи миёни риштаҳо нуқтаи оптималӣ байни харҷи сабзавот ва ҳосилоти ниҳоӣро муайян мекунад. Барои лӯбиё, тавсия мешавад, ки нақши «ду риштаи мувозӣ бо фосилаи 45 сантиметр» ҳамчун асоси оғоз истифода шавад.</p>\n<h3>Назорати чуқурии парвариши риштаҳо</h3>\n<p>Фосилаи муқобилавии риштаи нафас ғайри ягона метгавир нест; чуқурии парвариш низ нақш дорад. Агар ришта дар сатҳи хок парвариш шавад, буғубории намӣ ва коҳиши ришта аз сабаби мушҳо ва ҳашарот зиёд мегардад. Ришта бояд дар чуқурии 10 то 15 сантиметри хок ҷойгир карда шавад, ки бо буғуборҳои асосии решаҳои лӯбиё ҳамсатҳ бошад.</p>\n\n<h2>Ҷавоб ба саволҳои мураттаб (FAQ)</h2>\n<h3>1. оё мо метавонем як ришаи намунаи ороширо аз роҳи дорамунаро иваз кунем, на ба риштаспастани риштаҳо?</h3>\n<p>Бале, дар фосилаҳои дорамун беш аз 60 сантиметр, ҷойгиркунии ришаи марказӣ метавонад манлиқ бошад. Аммо дар фосилаҳои стандартии 45 то 50 сантиметр, спастани риша ба ҳар дорамун ё ришаҳои дукарата пӯшиши беҳтари риштаҳоро таъмин мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-عدس-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت عدس: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>drip tape spacing row layout crop эдас</figcaption></figure>\n<h3>2. нақши навъи хок дар тағйири фосилаи риша чист?</h3>\n<p>Дар хокҳои гилӣ, фосилаҳо бояд каме кушодатар (55-65 сантиметр) бошанд, то намдорӣ зуд ба риштаҳо расад ва ҷӯи оби ғамгор ба вуҷуд наояд. Дар хокҳои риғот, фосилаҳо пӯшида (45-50 сантиметр) метавонанд бошанд, зеро риштаҳо барои даспаст ба об зиёда паҳлӯ пайвастанд.</p>\n<h3>3. оё фосилаи ришаи намуна бо камбудии об дар минтақа алоқаманд аст?</h3>\n<p>Дар минтақаҳои камобӣ, истифодаи фосилаҳои наздиктар байни ришаҳо сабаб ба вуҷуд овардани ошқори ришаи намдорият дар риштаҳо мешавад ва ҳосилнокии обро зиёд мекунад, аммо бо назардошти сармоягузорӣ, ҳисоботи иқтисодӣ бояд анҷом дода шавад.</p>\n\n<h2>Хулоса ва натиҷагири</h2>\n<p>Мавзӯъ <strong>Фосилаи пӯши рафти ғурусҳо дар кишт</strong> Ин як параметри санҷидашуда (Site-specific) аст, ки ба омилҳои гуногун вобаста аст. Аммо дар рӯзмарра, риъоя кардани фосилаи 45 то 60 сантиметр барои сатрҳо, ба ҳамагӣ бо насб дурусти пӯши рафти ғурусҳо дар амиқии решаҳои фаъол, метавонад боиси афзоиши зоҳири сифати дона ва кам шудани истифодаи об гардад. Муаллифони муваффақтар онҳоянд, ки асосан баъд аз намуди хок ва иқлими минтақаи худ, намунаи «сатр дуроҳа» ё «пӯши марказро» бо дақиқати таҳқиқоти маҳаллӣ ҷойгир карда намоянд. Бо омӯзишҳои иловагии мисли <a href="https://navar-abyari.ir/mikorit-khomi-yufa-hamadoni-dar-hektar/">Истифодаи майкориза дар дарахтаро</a> ва идоракунии зичии кишт, метавон аз тамоми имкониятҳои системаи обёрӣ баъди ғурусҳо барои ғурусҳо истифода вард.</p>','Фосилаи навони тибишӣ дар парҳези нуқли: стандарти тавсияшуда','Интихоби фосилаи мувофиқ барои ҷойгиркунии тӯзори қатра (тип) дар куштубории лубия таъсири мустақиме дорад ба вайроншавии решаҳо, самаранамойии иқтисодӣ ва идоракунии об. Дар ин мақолаи navar-abyari.ir, мо меҳварҳои тиллоии барои ҷойгиркунии сафҳо ва навиштори системаи тӯзори қатра (тип)-ро таҳлил мекунем.','publish','closed','closed','fasila-navoni-tipish-o-kish-nuql-standard',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
