INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','فاصله نوار تیپ في زراعة الثوم: المعايير الموصى بها' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','دليل كامل للمزارعین العراقيين حول فاصله نوار تیپ في زراعة الثوم، مع معايير التقنیة والموصى بها لضمان أفضل المحصول. تشمل الممارسات الزراعية الحديثة والتوصیات الميدانیة.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
