INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар бораи аҳамияти дақиқ кардани масофаи шити нӯри писта</h2>\n<p>Коркардашавии нӯри писта яке аз ҳосилҳои деҳқонии ҳассостарин аз ҷиҳати идоракунии намии хок аст. Дар системаҳои нӯрпашории навории (Drip Tape), муайян кардани <strong>масофаи шити нӯри писта</strong> нақши муҳимро дар муайян кардани самаранокии ҳосил ва пешгирии бемориҳои қарадӣ иҷро мекунад. Бисёр деҳқонҳо танҳо асосан ба шухдат амал мекунанд, вале додаҳои техникӣ нишон медиҳанд, ки устувории намӣ дар минтакаи реша ба таври мустақим ба масофаи амудӣ ва афқии шити аз сатҳи хок ва маркази саф вобаста аст. Ин устуворӣ на танҳо барои рӯиш бароришӣ таъсиррасон аст, балки бевосита ба эҳодот ва пухтории деҳқоноии нӯри писта, ки маркази асосии иқтидори иқтисодии ин ҳосил аст, таъсир мерасонад. Агар намӣ бо тарзи дуруст тақсим нашуда бошад, деҳқон бо ду мушкилати ҷиддӣ рӯ ба рӯ мешавад: ё фишори хушкӣ, ки боиси парокандагии гул мешавад, ё таркиш, ки боиси пӯсидагии техникӣ мегардад.</p>\n<p>Дар ин мақола, дар чорчӯбаи баррасии меъёрҳои техникӣ, ба тарҳкунии дурусти сафҳо (Row Layout) дар деҳқонии нӯри писта ишора карда шудааст. Мақсади мо пешниҳоди як харитаи роҳи амалӣ барои кам кардани истеъмоли об ва зиёд кардани ҳосили деҳқоноии нӯри писта мебошад. Илова бар ин, таҳлили хароҷоти амалӣ ва беҳтар кардани захираҳои инсонӣ низ дар ин раванд нақши марказӣ дорад. Агар ҷустуҷӯи дарки амиқтари бенавъи қубурҳо ва филтрҳоро кор кунад, метавонед бо омӯзиш <a href="https://navar-abyari.ir/types-of-drip-tape-irrigation-tubes/">бенавъи шитҳои нӯрпашории қатрагӣ</a> шиносӣ бештар пайдо кунед. Фаҳмиши ин таҷҳизот ба шумо имкон медиҳад, ки матнҳои техникӣро беҳтар фаҳмед ва дар амалияҳои худ дақиқтар бошед.</p>\n\n<h2>Меъёрҳои техникӣ оид ба масофаи шити нӯри писта</h2>\n<h3>Таъсири чуқурӣи нобуд кардан бар интихоби фософа</h3>\n<p>Сир одатан дар чуқурӣи 3 то 5 сантиметр ғарз мешавад. Фосфаи нобирипӣ аз маркази сутун бояд чунин танзим шавад, ки намнокӣ дар қуллаи нобирипӣ (нуқтаи наздиктарин ба реша) ба ҳадди аксар расад. Агар фосфаи нобирипӣ аз деворчаи сутун (хат) зиёд бошад, қисми миёнаи сутун аз дашманиши хушкӣ азият мебинад. Аз тарафи дигар, агар нобирипӣ беш аз ҳад ба сатҳ наздик бошад, намнокии иловагӣ метавонад сабаби пайдоиши бимарии қумарӣ дар қисми таҷи равон гардад. Бинобар ин, пайдо кардани нуқтаи мувозунат миёни чуқурӣи ғарз ва фосфаи фокии нобирипӣ, калиди муваффақият дар идоракунии оборӣ мебошад. Ин мувозунат бояд бо назардошти намуди хамчун ҳармонкунӣ шавад; зеро хамчунҳои вазнин ва сабук рафтори гуногун дар баробари даромадани об доранд.</p>\n<ul>\n<li><strong>Фосфаи фоқии аз деворча:</strong> Масҳеб карда мешавад, ки нобирипӣ дар фосфаи 10 то 15 сантиметр аз деворчаи бетонӣ ё хамчунӣ сутун ҷойгир шавад.</li>\n<li><strong>Фишори хат:</strong> Дар хатҳое, ки диаметрашон 16 миллиметр аст, фишори кории мувофиқ барои нигоҳ доштани якхелагии ҷараён тақрибан 1 то 2 бар мебошад. Тағйироти фишор бояд ба ҳадди ақалс арзингӣ гардад.</li>\n<li><strong>Деби қатраҳо:</strong> Бо назардошти ниёзи обии кам, вале мунтазами сир, нобирипие, ки деби онҳо 2 литр дар соат аст, афзалтар мебошанд. Деби балотар метавонад хатарнок бошад.</li>\n</ul>\n<p>Барои гирифтани маълумоти дақиқтар оҳанги ҳисоб кардани ҷараён ва диаметр мувофиқи лӯлаҳои вом, метавонед ба <a href="https://navar-abyari.ir/%d8%b7%d8%b1%db%8c%d9%82%d9%87-%d9%86%d8%b5%d8%a8-%d9%86%d9%88%d8%a7%d8%b1-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%aa%db%8c%d9%be/">рахномаи насби дурусти наворип</a> масъулат шавед. Ин раҳнома тафсилоти дақиқи насби қапҳо ва пайвастҳоро шарҳ медиҳад, ки таҳаммул насби онҳо метавонад боиси оғузи об гардад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-سیر-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت سیر: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop сир</figcaption></figure>\n\n<h3>Намунаи ҷобаҷогузории сафҳо (Row Layout) дар садиҳои сир</h3>\n<p>Ҷобаҷогузории сафҳои сир одатан аз ҷиҳати ду саф (сир ду сафӣ) ё як саф бо роҳи гилкунан насб мегардад. Дар намунаи ду сафӣ, масофа байни гилкунанҳо бояд ҳадди ақал 50 то 60 сантиметр бошад, то ки фазои кӯфӣ барои гузаштани навор ва идоракунии сир ва ҳаво вуҷуд дошта бошад. Масофаи наворип аз сатҳи хок (ҳол, ки бунъодан поёнӣ ба хок асбоб шуд) бояд ҳадди ақал 3 сантиметр бошад, то ки намнокӣ мустақиман ба лабаҳои реша расад ва боиси кордон нашад. Риояи ин масофаҳо имкон медиҳад, ки гардиши ҳаво дар сад беҳтарин тарзи иҷро шавад ва аз ҷамъ омадани зиёдатии намнокӣ пешгирӣ кунад. Инчунин, самти сафҳоро бояд бо назардошти самти шабонаравии ҳаво дар минтаҳа назар дошта шавед, то ки поёни гиёҳӣ якнавохттар бошад.</p>\n<p>Бехатариҷокунии ҷобаҷогузории сафҳо бевосита ба ҳисобкунии наворҳои фибер тики таъсир мерасонад. Дар ин ҷо як ҷадвали роҳнамо барои мувофиқ кардани масофаҳо бо шароити хок:</p>\n<table>\n<thead>\n<tr>\n<th>Навъи хок</th>\n<th>Дараи кордани сир</th>\n<th>Масофа аз риштагӣ то девор</th>\n<th>Шарҳи амалиётӣ</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Рег</td>\n<td>3-4 сантиметр</td>\n<td>10 сантиметр</td>\n<td>Захираи об кам аст; риштагӣ наздиктар ба маркази сатҳ.</td>\n</tr>\n<tr>\n<td>Рест</td>\n<td>4-5 сантиметр</td>\n<td>15 сантиметр</td>\n<td>Тақсимоти беҳтари намӣ; имконияти бештари фосилагӣ.</td>\n</tr>\n<tr>\n<td>Лумӣ</td>\n<td>5 сантиметр</td>\n<td>20 сантиметр</td>\n<td>Хавфи ҷамъшавии намӣ; ниёз ба фосилаи бештар аз марказ.</td>\n</tr>\n</tbody>\n</table>\n\n<h2>Нуқтаҳои амалӣ ва иҷроӣ дар идоракунии обёрӣ ба сир</h2>\n<h3>Коркардкунӣи кӯрпусти ва бемориҳои реша</h3>\n<p>Яке аз хатогиҳои маъмул дар парвариши сир, намдории минтақаи реша тавассути обори зиёд аст. Риштаи нӯкии бо оҳистагии мувофиқ имконияти идоракунии дақиқи намнокроӣро фароҳам меорад. Вақте аз системаи риштавӣ истифода мебаред, ҳатман масофаи охирини ришта то охирини қатраҳоро санҷед, то оҳистаги берави тарҳбандӣ бошад. Агар дар охирини хат оҳистаги дида шавад, шидати замин ё сифати риштаи нӯкиро таҳқик кунед. Шаҳси намуди ифроби оҳистагиро ва кори ҳар яке саҳм мекунад, ки модели мувофиқро барои замини ластук ва сангло доред. Инчунин, хамзакӯбҳои кимиёвӣ низ бо эҳтиёт истифода шаванд, то решаи ботинҳо ба ришта таҳмил надиҳад.</p>\n<h3>Шумордани оҳистагӣ ва ғизонокунӣ</h3>\n<p>Сир дар давраи рушди ботинӣ ба нитратҳои аммоний лозим дорад. Истифода аз риштаи нӯкии имконияти фертигисатсияро фароҳам меорад. Вақте ғизонокунӣ ва обро ҷуфт мекунед, ҳатман аз филтери 80 мультисел истифода баред, то хуфшавии қатраҳо ба ҳадди ақал орад. Инчунин, санҷиши чуқурбии реша бо истифода аз маирумметр пеш аз ҳар даври оҳистагӣ тавсия мешавад. Ғизонокунии риштавӣ имкон медиҳад, ки моддаҳои ғизоӣ дақиқан дар минтақаи қабули реша ҷамъ шаванд ва парҳезҳои ғизонокунӣ коҳиш ёбанд. Дар қисми охир, барои омӯзиши дигар маҳсулот дар ин ҳамон система, шумо метавонед <a href="https://navar-abyari.ir/musir-seed-per-hectare-yield-increase/">Роҳнамоӣ барои зиёд кардани ҳосили арз</a> -ро низ омӯзед. Ин муқоиса барои фаҳмидани беҳтари потенсиали системаи риштавӣ дар маҳсулотҳои гуногун кӯмак мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-سیر-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت سیر: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>drip tape spacing row layout crop сир</figcaption></figure>\n\n<h3>Техникаҳои иловагӣ ва фишоркуниҳо</h3>\n<p>Истифодаи регулятори фишор дар ибтидои хат, пастаиднокунии равони қатраҳоро ҳатто дар соатҳои гармии рӯз таъмин мекунад. Носеҷеши фишор беш аз 15 фоиз метавонад боиси тақсимоти ноҳамвор намҳо ва хушкӣ дар қисмҳои пасткунҷи шабака гардад. Инчунин, филтърҳои мувофиқ барои пешгирии даромадани зарраҳои муваққатӣ ба система бояд ба даъватии доимӣ нигоҳ дошта шаванд. Таъмироти мунтазами ин таҷҳизот аз самаранокӣи умумии системаи обӣ маҳфуз менамояд ва умри фоидабахши пайпҳоро зиёд мекунад. Хароҷоти нигоҳдорӣ бояд дар моделбарории иқтисодиёти боғ ҷараён дода шавад.</p>\n\n<h2>Ҷавоб ба саволҳои маъмул (FAQ)</h2>\n<h3>Беҳтарин намуди пайп ҳангои барои буғдолбӣ кадом аст?</h3>\n<p>Пайпҳои тарҳе (Inline Drip) бо қатраҳои дохилидӣ ва диаметри 16 ё 19 миллиметр барои буғдолбӣ идеалӣ мебошанд. Ин пайпҳо умри баланд доранд ва дар баробари фишорҳои механикӣ ҳангои кирошт бардакортар мебошанд. Пайпҳое бо қабати муқобили UV барои нигоҳдории дар тӯли фасл тавсия дода мешаванд. Сифати пайпи PVC ва пайвасткуниҳо ҳам бояд дараҷаи аввал бошад, то ки аз шикасти ғубурӣ пешгирӣ шавад.</p>\n<h3>Фавоси пайп ҳангои аз деворки бетонӣ чанд мешавад?</h3>\n<p>Дар буғдолбӣ ки дар тухтибанд кирошт шудааст, фавоси 10 то 15 сентиметр аз деворки пасткунҷи бетонӣ стандарт аст. Ин фавос боиси он мегардад, ки минтақаи асосии решаҳо (одатан 15 сентиметр аз рӯи замин) пурраи намнок гардад. Дар сурати вуҷуди хирӣ ё дигар заҳромҳои решагӣ, ин фавос метавонад каме тағйир ёбад.</p>\n<h3>Оё мумкун аст, аз пайп ҳанго бо равони 3 литр барои буғдолбӣ истифода барем?</h3>\n<p>Истифодаи равони 3 литр дар буғдолбӣ хатари пуфидани зарароварро зиёд мекунрад, магар ҳарфи обдоӣ хеле кӯтоҳ бошад. Барои бехатарӣ, равони 2 литр бо вақти дарозтари обдоӣ интихоби дурустар аст. Назорати намҳои замин пас аз ин обдои метавонад ба беҳтаркунии фавосҳои оянда кӯмак расонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-سیر-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت سیر: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>мавозии лентабарии қатқоркашӣ ҷойгиркунии сафҳо ҳосил сибу ҷӯ</figcaption></figure>\n\n<h3>Таъсири шудори замин ба масофаи навар чист?</h3>\n<p>Дар заминҳои душтафш, равонӣ дар хати сердуштафтарин зиёдтар хоҳад буд. Барои ҷуброни ин мушкилот, таҷҳизоти танбеи фишори мутобиқ (Pressure Compensating Drip)-ро истифода баред ё шудори хамистро камтар аз 1 фоиз нигоҳ доред. Тасвифи дақиқи замин пеш аз насби навар қадами аввал барои муваффақият аст. Истифодаи лазери танбекунаркунанда дар деҳқониҳои калон даққадро баланд мебардорад.</p>\n<h2>Хулоса ва тавсияи охирин</h2>\n<p>Аҳамияти... <strong>Масофаи навартип дар кӯшт шудани сибу ҷӯ</strong> Як параметр сода ба назар мерасад, аммо таъсири мустақими дорад ба сифати решаҳо, муқовимати ба бемориҳои зангорӣ ва дар ниҳоят вазни меҳнаки. Имоме аз андешаҳои нодуруст ва истифодаи маълумотҳои хокишиносӣ барои танбеи чуқурӣ ва масофаи навар сармоягузориҳои дурандкор аст. Бо назардошти аҳамияти даққа дар насб, пешниҳод мекунем, ки пеш аз оғози fasli кушт, як хати санҷишӣ гузоред ва кори онро бо назорати намии зероӣ санҷед. Ин равиш на танҳо истеъмолро обро кам мекунад, балки хатари камшавии истеҳсолро ба ҳадди ақал мерасонад. Инчунин, ҳуҷҷатсозии маълумотҳои ҳар фасл барои беҳбуди солҳои оянда зарур аст.</p>\n<p>Дар охир, барои огоҳӣ аз масофаҳои монанди дигар маҳсулоти зироатӣ монанди шигор ҷӯ, шумо метавонед роҳнамои <a href="https://navar-abyari.ir/corn-drip-tape-spacing-forage-corn-guide/">Фосилаи сунбурҳои гандумони</a> ро омӯзна, то дар бораи системаҳои сунбури дар маҳсулоти гуногун диди пурратар дошта бошед. Ин таҳқиқоти муқоисавӣ ба деҳқон имкон медиҳад, ки аз таҷрибаҳои худ барои беҳтарсозии парвариши моли (себ) истифода барад ва ҳосили умумии заминашро зиёд намояд.</p>','Фовсу байнои банд дар кӯрҳои сир: Стандартҳои тавсияшуда','Ошно шудан бо беҳтарин масофаҳои зерибони хурмо дар партоварии сир, роҳи ҷойгир кардани қаторҳо ва нуқтаҳои иҷрошавӣ барои пешгирӣ аз зарари обнокӣ ва беҳтар кардани сифати сир дар ҳаро.','publish','closed','closed','farase-nevar-tip-dar-kushat-e-sir',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
