INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти танзими дурусти нӯри (шланги) нӯрӣ дар мӯсор</h2>\n<p>Заръи мӯсор дар Тоҷикистон яке аз муҳимтарин фаъолиятҳои кишоварзӣ аст, ки ба эҳтиётии баланд дар идоракунии обкорӣ ниёз дорад. яке аз муҳимтарин параметрҳое, ки бисёре аз деҳқонон онро кам баҳодиҳӣ мекунанд, <strong>масофаи нӯри нӯрӣ дар мӯсор</strong> ва усули ҷойгир кардани он нисбат ба сафҳои заръ аст. Танзими нобудовар метавонад боиси обкориёи нокифоя, бемориҳои реша ва кам шудани ҳосилнокии маҳсул дар ҳекар шавад. Дар ин қисм, мо стандарди тавсияшударо барои оптимизатсияи ҷойгиркунии сафҳо ва масофаи нӯрҳоро баррасӣ мекунем.</p>\n\n\n\n<h2>Асосҳои ҷойгиркунии сафҳо (Row Layout) ва масофаи нӯр</h2>\n<p>Барои фаҳмиши беҳтар <strong>масофаи нӯри нӯрӣ дар мӯсор</strong>аввалан бояд ба масофа байни ду саф ва ҷойи физикии нӯр дар бисм ё кодон диққат диҳем. Масофаи стандардии муайяншуда барои нӯрҳо бевосита ба нақшаи хобидан (Wetting Pattern) таъсир мерасонад.</p>\n<h3>Таъсири масоҳати байни қаторҳо ба интихоби нах</h3>\n<ul>\n<li><strong>Масоҳати стандартии байни қаторҳо:</strong> Одатан масоҳати байни ду қатори сардом 25 то 30 сантиметр мебошад. Нах бояд дақиқан аз маркази ин масоҳат гузарад, то ки решаҳои ҳарду қатори ҳамсояро пурра фаро гирад.</li>\n<li><strong>Нахи яксояна ё душонана:</strong> Бо назардошти масоҳати кам байни қаторҳо, истинод аз нахҳое тавсия дода мешавад, ки токи бародаро баробар тақсим кунанд.</li>\n<li><strong>Кунҷи насб:</strong> Нах бояд бо ниҳоки нимсатҳ ба сӯи реша ҷойгир карда шавад, то ки ҷараёни об аз баргҳо дур бошад ва мустақиман ба минтақаи реша раسد.</li>\n</ul>\n\n<h2>Параметрҳои техникии нах барои сардом</h2>\n<p>Интихоби намуди лентаву ва фосилаи бандукҳои он қисми муҳими мавзӯъи фосилагузории физикӣ аст. Барои моҳи, ки яхбон ва ба рағбати устувор ниёз дорад, устувории ҷараён ҳаётӣ аст.</p>\n<h3>Ҳуҷҷатҳои техникии тавсияшуда</h3>\n<table>\n  <thead>\n    <tr>\n      <th>Параметр</th>\n      <th>Миқдори тавсияшуда</th>\n      <th>Сабаби техникии</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td> Диаметри дохилии лентаву</td>\n      <td>16 миллитр</td>\n      <td>Басоати устувори ҷараён барои тамоми даври афзоиш</td>\n    </tr>\n    <tr>\n      <td>Фосилаи пеллҳои drip tape</td>\n      <td>20 сантметр</td>\n      <td>Пӯшиши равшан дар атрофи решаҳо дар ҳарду ҷони ришта</td>\n    </tr>\n    <tr>\n      <td>Суръати ҷараён</td>\n      <td>Аз 1.6 то 2.0 литр дар як соат</td>\n      <td>Мувофиқ бо суръати беҳтарини обдорӣ барои шашлик</td>\n    </tr>\n  </tbody>\n</table>\n\n<p>Барои омӯзиши дақиқтар ҳуҷуми маълумотҳои техникӣ дар бораи муҳимоти риштаи оборӣ, таваҷҷуҳ ба фойлҳои коркунаги зарур аст. Тағйироти ин стандартҳо метавонад ба вуҷуд овардани нуқтаҳои хушк дар атрофи решаҳо бошад, ки барои шашлик зараровар аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-موسیر-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت موسیر: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop шашлик</figcaption></figure>\n\n\n\n<h2>Нуқтаҳои амалии насб ва нигоҳдорӣ</h2>\n<p>Ҳатто агар <strong>Фаволи чилбандии навоз барои бӯса</strong> бо дуруст ҳисоб шуда бошад, иҷрои дурусти он дар майдон қувваи ниҳоии муваффақиятро муайян мекунад. Дар ин қисм нуқтаҳои асосии амалииро мунтазам дорем.</p>\n<h3>Техникаҳои насби дуруст</h3>\n<ol>\n<li><strong>Тоза нигоҳ доштани филтрҳо:</strong> Барои ҳассос будани система ба ҷамъшавии арзишҳо, бояд филтрҳо ҳар 48 соат санҷида шаванд. Филтри гирифторӣ метавонад сарроҳии навозро кам карда, якхелии фаволаи қатраҳоро вайрон кунад.</li>\n<li><strong>Пайвастшавӣ ба шланги асосӣ:</strong> Рынг бояд бо клипҳои стандартӣ ба лӯлаи асосӣ пайваст шавад. кашиш аз ҳад зиёд ё пайвасти боз, боиси хориҷи ғайриоддӣ ё ришиши нобаёди ришҳо мегардад.</li>\n<li><strong>Коркардӣ бегӣ ё пот:</strong> Бегӣ ё пот бояд аз риш тақрибан 5 то 10 сантиметр дур бошад. Ҷойгир кардани бегӣ рост дар риш боиси сӯзишӣ нисбӣ ва бемории занг дар марҳалаи бардошӣ мегардад.</li>\n<li><strong>Баррасии биназурӣ:</strong> Баъд аз об кардани аввал, сати заминро дида бароед. Замин дар радиус 15 то 20 сантиметр аз риш бояд тар бошад ва замин дар радиус калонтар бояд хушк бошад.</li>\n</ol>\n\n<p>Агар аз системаи лӯлагузории собит истифода баред, санҷед, ки оё шурандагии замин ба таврест, ки фишор дар охири риш паст наафтад. Афтиши фишор метавонад боиси он шавад, ки қатраҳо дар охири риш камтар партофта шаванд ва шаблонни тарроҳиро тағир диҳад. Барои шиносӣ бо асосҳои умумии системаҳои собит, мақолла обирории мустақими заминро хонед: арзандӣ ва нуқсонҳо.</p>\n\n<h2>Таъсири масофаи риш ба ҳосил ва сифати сиёҳӣ</h2>\n<p>Алоқаи мустақим байни сифати обкунӣ дар минтакаи ришҳо ва ҳаҷми ниҳоии ҳосил вуҷуд дорад. Вақте ки <strong>Фосилаи нӯри чумпоқ дар мўғри</strong> Агар оптималӣ бошад, ғилоз метавонад аз тамоми қобилияти замин истифода барад. Кам шудани решагӣ сабаби стресси обёрӣ метавонад боиси хурд шудани пиёзҳо ва кам шудани вазни ҳалқаи мўғри гардад.</p>\n\n<p>Барои муқоиса, бисёр деҳқонон дар ҳисоб кардани зичии кишт хато кардаанд. Барои расидан ба ҳосилии максималӣ, бояд донист, ки дар ҳектар чанд нола киштрошудан мумкин аст. Раҳнамои умумӣ <a href="https://navar-abyari.ir/shallot-seed-quantity-per-hectare-guide/">Микдори боди мўғри дар ҳар ҳектар</a> ҳатман хонед, то зичии киштатон бо фазои дар дастраси нӯриҳо мувофиқат кунад. Агар фосилаи нӯриҳо аз зичии кишт камтар бошад, ғилозҳо рақобати шадид барои ҷабби об мекарданд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-موسیر-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت موسیر: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>drip tape spacing row layout crop мўғри</figcaption></figure>\n\n<h2>Саволҳои муқарарӣ (FAQ)</h2>\n<h3>1. Оё мумкин аст аз нӯри чумпоқи собит дар мўғри истифода барем?</h3>\n<p>Бале, лентҳои сипи собит (Fixed Spray Tape) метавонанд танзимоти мувофиқ бошанд, хусусан агар фосила байни силсилаҳо тағйирёбад. Ин лентаҳо пурраии беҳтари ҷараёнро дар муқобили фишори тағйирёбанда доранд. Барои шиносӣ бештар, роҳнамоии <a href="https://navar-abyari.ir/%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%ab%d8%a7%d8%a8%d8%aa-fixed-spray-tape/">лентҳои сипи собит Fixed Spray Tape</a> ро баррасӣ кунед.</p>\n<h3>2. Кай бояд лентаҳо дар сабзавот иваз карда шаванд?</h3>\n<p>Одатан давоми фаъолияти лентаи сип як мавсим аст. Бо назардошти ҳиссиёти сабзавот ба решагӣ, ивази лента дар ҳар давраи кишт тавсия дода мешавад, то аз гирифторшавии сӯрохиҳо ва камшави самаранокӣ пешгирӣ карда шавад. Инчунин баррасии роҳҳои зиёд кардан самаранокӣ ва самаранокӣи лентаи сип барои таълифотҳои фаннӣ ва нигоҳдорӣ метавонад фоидабахш бошад.</p>\n<h3>3. Оё фосилаи лента барои бӯм ва лӯлаи бӣ фарқ дорад?</h3>\n<p>Бале. Вақти истифодабарии лӯлаи бӣ, фосилаи бӯм аз лента бояд мувофиқи дастурамали лента бошад, то лӯлаи бӣ нагузарад. Дар бӯм, онро метавон каме пасин ҷойгиранд, то ки пас аз нӯм кардан, раста ба таври табиӣ аз намии лента истифода барад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-موسیر-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت موسیر: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>дурнамои фосилаи лентаи сип тартиби силсилаҳо заръ сабзавот</figcaption></figure>\n\n<h2>Хулоса ва тавсияҳои ниҳоӣ</h2>\n<p>Танзим <strong>Фосилаи намунаи тири дар шевпола (musir)</strong> Ин раванд аст, ки бевосита ба хулосаҳои иқтисоди шумо таъсир мерасонад. Бо риояи принсипҳои ҷойгиркунии сафҳо (Row Layout), интихоби фосилаи стандартӣ 20 сентиметрӣ барои қатрапошӣ ва дақиқӣ дар насб, шумо метавонед хатари бемориҳои решаҳоро ба ҳадди ақалл расонида ва рушди якнавои пиёзҳоро таъмин кунед. Ҳамisha аз манбаъҳои муосир барои санҷиши тағйирот дар намунаи рушди шевпола истифода баред. Агар дар барномарезӣ барои паҳлукҳои баъдӣ ба роҳнамоӣ ниёз дошта бошед, таҳқиқи мақолаҳои марбут ба ҳаҷми ғунҷишгирии қатқи элӣ дар ҳектар метавонад дар фаҳмидани намунаи умумии рушди рӯғонҳои баҳорӣ то тӯбӣ бозёби бодад, гарчанде ки шевпола рӯғоне бо намунаи рушди гуногун аст.</p>\n\n<p>Устувори системаи обёрӣ танҳо бо нигоҳдории давоми мумкин аст. Ҷаҳиши филтр, фишордиҳанда ва намунаҳо, калиди асосии нигоҳ доштани коркунандаи лоиҳа дар давоми мавсими рушд аст.</p>\n\n\n<p><strong>Мавзӯи марбут:</strong> <a href="https://navar-abyari.ir/%d8%aa%d9%86%d8%a7%da%98-%d9%87%d9%86%d8%af%d9%88%d8%a7%d9%86%d9%87-%d8%aa%d8%ae%d9%85%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми гардиши арбузи хом дар ҳектар: омилҳои таъсиррасон + роҳҳо барои афзоиш</a>, <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%B0%D8%B1%D8%AA-%D8%B9%D9%84%D9%88%D9%81%D9%87%D8%A7%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA D8B0D8B1D8AA D8B9D984D988D981D987D8A7DB8C D8AFD8B1 D987DAA9D8AAD8A7D8B1</a></p>','Фосилаи Нӯри Тип Дар Заръи Посиш: Стандарти Тавсияшуда','Машварати ихтисосӣ дар бораи танзими масоҳати намунаҳои тиби дар анзур, беҳтарсозии ҷойгиркунӣ аз раҳоҳо ва принсипҳои дурусти обёрӣ-буттабарӣ барои баландбардории ҳосилнокӣ ва камрасидан ба хароҷот.','publish','closed','closed','fosilaai-nuri-tip-dar-zary-posish-standardi-tavsiashuda',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
